        excludeFiles: [
          "**/*.test.ts",
          "**/*.test.tsx",
          "**/*.test.mts",
          "**/*.test.cts",
          "**/*.spec.ts",
          "**/*.spec.tsx",
          "**/*.spec.mts",
          "**/*.spec.cts",
          "**/tests/**",
          "**/generated/**",
          "**/dist/**",
          "**/*.d.ts",
        ],
        rules: { "tsdoc/syntax": "error", "tsdoc-require-2/require": "error" },
