  expect(summary.run).toContain("GITHUB_STEP_SUMMARY");
  expect(job.steps.some((step: { run?: string }) => step.run === "vp run audit:components")).toBe(
    true,
  );
  expect(
    job.steps.some((step: { run?: string }) => step.run?.includes("doctor --install-browser")),
  ).toBe(true);
});

