/**
 * @component table.row-header
 * @memberOf table
 * @selector th[scope="row"]
 * @a11y Use `<th scope="row">` so the cell names its row for assistive technology.
 * @summary A row-header cell (InstUI `Table.RowHeader`); styled from the row-header tokens, not the column-header ones.
 * @remarks The parent `table`'s `-layout-stacked` modifier stacks this member as a block and labels it via `::before` — see `table`'s own doc for that modifier.
 * @structure
 * @component table {
 *   tbody {
 *     tr {
 *       th[scope="row"] {}
 *     }
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <div class="pfx-view --overflow-x-auto -focus-position-inset -without-focus-animation" role="region" aria-labelledby="table-row-header-caption" tabindex="0">
 * <table class="pfx-table -hover">
 *   <caption id="table-row-header-caption">Top-rated films</caption>
 *   <thead>
 *     <tr>
 *       <th scope="col">Rank</th>
 *       <th scope="col">Title</th>
 *       <th scope="col">Year</th>
 *       <th scope="col">Rating</th>
 *     </tr>
 *   </thead>
 *   <tbody>
 *     <tr>
 *       <th scope="row">1</th>
 *       <td>The Shawshank Redemption</td>
 *       <td>1994</td>
 *       <td>9.3</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">2</th>
 *       <td>The Godfather</td>
 *       <td>1972</td>
 *       <td>9.2</td>
 *     </tr>
 *     <tr>
 *       <th scope="row">3</th>
 *       <td>The Godfather: Part II</td>
 *       <td>1974</td>
 *       <td>9.0</td>
 *     </tr>
 *   </tbody>
 * </table>
 * </div>
 * ```
 */
/* A row-header cell (th scope=row) — styled from the row-header tokens, not the column-header ones. */
.pfx-table tbody th,
.pfx-table th[scope="row"] {
  background: var(--instui-component-table-row-header-background);
  color: var(--instui-component-table-row-header-color);
  font-weight: var(--instui-component-table-row-header-font-weight);
  line-height: var(--instui-component-table-row-header-line-height);
  padding: var(--instui-component-table-row-header-padding-vertical)
    var(--instui-component-table-row-header-padding-horizontal);
}

/* No border of its own — the separator lives on the row (see table.row). Reset with tbody specificity
 (0,1,2) so a host stylesheet's cell borders (e.g. `.pantoken-prose td`, 0,1,1) can't leak in. */
.pfx-table tbody th {
  border: 0;
}

/* layout="stacked": stack as a block, labelled by its column via ::before (pure CSS can't pull the
 <th> text automatically, so the author supplies a `data-label` per cell). */
.pfx-table.-layout-stacked th {
  display: block;
  width: auto;
}

.pfx-table.-layout-stacked tbody th[data-label]::before {
  content: attr(data-label);
  display: block;
  font-weight: var(--instui-component-table-head-font-weight);
  color: var(--instui-component-table-col-header-color);
}

