/**
 * @component calendar.day
 * @memberOf calendar
 * @selector .day
 * @a11y Mirror `-selected` with `aria-selected` and mark today with `aria-current="date"`; give each day a full-date accessible name, since the day number alone is ambiguous.
 * @summary A day cell (InstUI `Calendar.Day`); `-today`, `-selected`, and `-outside-month` mark its state.
 * @modifier -today — Today's date.
 * @modifier -selected — The selected date.
 * @modifier -outside-month — A day from the adjacent month (leading/trailing filler).
 * @structure
 * @component calendar {
 *   .grid {
 *     .day {}
 *   }
 * }
 * @example -automatica11y
 * ```html
 * <div class="pfx-calendar" aria-label="March 2026"><div class="nav"><strong>March 2026</strong></div><div class="grid"><span class="weekday">Sunday</span><span class="day">1</span><span class="day -today">8</span><span class="day -selected">15</span></div></div>
 * ```
 */
@scope (.pfx-calendar) {
  .day {
    display: flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--instui-component-calendar-day-min-width);
    block-size: var(--instui-component-calendar-day-height);
    font-size: var(--instui-component-calendar-day-font-size);
    color: var(--instui-component-calendar-day-color);
    background: var(--instui-component-calendar-day-background);
    cursor: pointer;
  }

  .day.-outside-month {
    color: var(--instui-component-calendar-day-outside-month-color);
  }

  .day.-today {
    background: var(--instui-component-calendar-day-today-background);
    color: var(--instui-component-calendar-day-today-color);
    border-radius: var(--instui-component-calendar-day-today-border-radius);
  }

  .day.-selected {
    background: var(--instui-component-calendar-day-selected-background);
    color: var(--instui-component-calendar-day-selected-color);
    border-radius: var(--instui-component-calendar-day-selected-border-radius);
  }
}

