/**
 * @utility transition
 * @selector .pfx-transition.-transition-fade-entering
 * @modifier -transition-* — Transition type/state class toggled by runtime (`fade|scale|slide-*` + `entering|entered|exiting|exited`).
 * @global
 * @a11y The classes only animate, so provide a `prefers-reduced-motion` alternative for large movement and don't convey essential state through the transition alone.
 * @summary Animation state classes for the `Transition` component — `.instui-transition` and state classes (`-transition-fade-entering`, `-transition-scale-exited`, etc.) — usable bare or chained onto any component.
 * @cssproperty --duration — Animation duration (default `300ms`); override to speed up or slow down every transition state.
 * @cssproperty --timing — Animation timing function (default `ease-in-out`).
 * @example
 * <div class="instui-transition -transition-fade-entering">Animated content</div>
 */
@property --duration {
  syntax: "<time>";
  inherits: true;
  initial-value: 300ms;
}

@property --timing {
  syntax: "*";
  inherits: true;
  initial-value: ease-in-out;
}

@scope (.pfx-transition) {
  & {
    @media (prefers-reduced-motion: no-preference) {
      transition:
        opacity var(--duration) var(--timing),
        transform var(--duration) var(--timing);
    }
  }

  &.-transition-fade-exiting,
  &.-transition-fade-exited {
    opacity: 0.01;
  }

  &.-transition-fade-entering,
  &.-transition-fade-entered {
    opacity: 1;
  }

  &.-transition-scale-exiting,
  &.-transition-scale-exited {
    transform: scale(0.01) translate3d(0, 0, 0);
    opacity: 0.01;
  }

  &.-transition-scale-entering,
  &.-transition-scale-entered {
    transform: scale(1) translate3d(0, 0, 0);
    opacity: 1;
  }

  &.-transition-slide-right-exited,
  &.-transition-slide-left-exited,
  &.-transition-slide-up-exited,
  &.-transition-slide-down-exited {
    opacity: 0.01;
  }

  &.-transition-slide-right-exiting,
  &.-transition-slide-right-exited {
    transform: translate3d(100%, 0, 0);
  }

  &.-transition-slide-left-exiting,
  &.-transition-slide-left-exited {
    transform: translate3d(-100%, 0, 0);
  }

  &.-transition-slide-up-exiting,
  &.-transition-slide-up-exited {
    transform: translate3d(0, -100%, 0);
  }

  &.-transition-slide-down-exiting,
  &.-transition-slide-down-exited {
    transform: translate3d(0, 100%, 0);
  }

  &.-transition-slide-right-entering,
  &.-transition-slide-left-entering,
  &.-transition-slide-up-entering,
  &.-transition-slide-down-entering,
  &.-transition-slide-right-entered,
  &.-transition-slide-left-entered,
  &.-transition-slide-up-entered,
  &.-transition-slide-down-entered {
    transform: translate3d(0, 0, 0);
