/**
 * @component text
 * @selector .pfx-text
 * @a11y It sets appearance only and renders no semantics, so use `<p>`, `<strong>`, `<em>`, and similar elements for meaning, and check contrast of each `-color-*` against its background, especially the inverse colors.
 * @summary Body-text typography with size, weight, colour, and style modifiers.
 * @remarks The `-variant-*` presets and the `-color-*`/`-size-*`/`-weight-*` modifiers all compose on the same element; unlike `heading`, it renders no implicit semantic level.
 * @modifier -color-brand — Brand text colour.
 * @modifier -color-secondary — Secondary (muted) text colour.
 * @modifier -color-ai — @deprecated {@link -color-ai-highlight}
 * @modifier -color-ai-highlight — AI-accent text colour with background highlight.
 * @modifier -color-success — Success text colour.
 * @modifier -color-warning — Warning text colour.
 * @modifier -color-danger — Danger text colour.
 * @modifier -color-primary — Primary text colour.
 * @modifier -color-primary-inverse — On-dark (primary inverse) text colour.
 * @modifier -color-secondary-inverse — On-dark (secondary inverse) text colour.
 * @modifier -color-secondary-on — Secondary text colour on a coloured background.
 * @modifier -color-primary-on — Primary text colour on a coloured background.
 * @modifier -weight-bold — Bold weight.
 * @modifier -style-italic — Italic.
 * @modifier -transform-uppercase — Uppercase the text.
 * @modifier -transform-lowercase — Lowercase the text.
 * @modifier -transform-capitalize — Capitalise each word.
 * @modifier -variant-description-page — Page-description type preset.
 * @modifier -variant-description-section — Section-description type preset.
 * @modifier -variant-content — Content type preset.
 * @modifier -variant-content-important — Important-content type preset.
 * @modifier -variant-content-quote — Quote-content type preset.
 * @modifier -variant-content-small — Small-content type preset.
 * @modifier -variant-legend — Legend type preset.
 * @modifier -size-xs — Extra small.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @modifier -size-xl — Extra large.
 * @example -canvas-rce -docs
 * ```html
 * <span class="pfx-text -size-xs --display-block">x-small text</span>
 * <span class="pfx-text -size-sm --display-block">small text</span>
 * <span class="pfx-text -variant-content-quote --display-block">Quoted text</span>
 * <span class="pfx-text -color-ai-highlight">AI highlight text</span>
 * ```
 * @related heading — Typography for headings rather than body text.
 * @related truncate — Clips this text to one line or a set number of lines.
 * @stable
 * @sealed
 * @example -automatica11y
 * ```html
 * <span class="pfx-text -size-xs --display-block">x-small text</span>
 * <span class="pfx-text -size-sm --display-block">small text</span>
 * <span class="pfx-text -variant-content-quote --display-block">Quoted text</span>
 * <span class="pfx-text -color-ai-highlight">AI highlight text</span>
 * ```
 */
@scope (.pfx-text) {
  & {
    font-family: var(--instui-component-text-content-font-family);
    color: var(--instui-component-text-base-color);
    font-size: var(--instui-component-text-font-size-medium);
    font-weight: var(--instui-component-text-font-weight-normal);
    line-height: var(--instui-component-text-content-line-height);
  }

  &.-size-xs {
    font-size: var(--instui-component-text-font-size-x-small);
  }

  &.-size-sm {
    font-size: var(--instui-component-text-font-size-small);
  }

  &.-size-lg {
    font-size: var(--instui-component-text-font-size-large);
  }

  &.-size-xl {
    font-size: var(--instui-component-text-font-size-x-large);
  }

  &.-weight-bold {
    font-weight: var(--instui-component-text-font-weight-bold);
  }

  &.-style-italic {
    font-style: italic;
  }

  &.-color-primary {
    color: var(--instui-component-text-primary-color);
  }

  &.-color-secondary {
    color: var(--instui-component-text-muted-color);
  }

  &.-color-brand {
    color: light-dark(
      var(--instui-color-institutional-brand-primary),
      var(--instui-color-institutional-brand-font-color-dark)
    );
  }

  &.-color-success {
    color: var(--instui-component-text-success-color);
  }

  &.-color-danger {
    color: var(--instui-component-text-error-color);
  }

  &.-color-warning {
    color: var(--instui-component-text-warning-color);
  }

  &:is(.-color-ai-highlight, .-color-ai) {
    color: var(--instui-component-text-ai-color);
    background: var(--instui-component-text-ai-background-color);
  }

  &.-color-primary-inverse {
    color: var(--instui-component-text-inverse-color);
  }

  &.-color-secondary-inverse {
    color: var(--instui-component-text-inverse-color);
  }

  &.-color-primary-on {
    color: var(--instui-component-text-base-on-color);
  }

  &.-color-secondary-on {
    color: var(--instui-component-text-muted-on-color);
  }

  &.-variant-description-page {
    font-size: var(--instui-component-text-description-page-font-size);
    font-weight: var(--instui-component-text-description-page-font-weight);
    line-height: var(--instui-component-text-description-page-line-height);
  }

  &.-variant-description-section {
    font-size: var(--instui-component-text-description-section-font-size);
    font-weight: var(--instui-component-text-description-section-font-weight);
    line-height: var(--instui-component-text-description-section-line-height);
  }

  &.-variant-content {
    font-size: var(--instui-component-text-content-font-size);
    line-height: var(--instui-component-text-content-line-height);
    font-weight: var(--instui-component-text-content-font-weight);
  }

  &.-variant-content-small {
    font-size: var(--instui-component-text-content-small-font-size);
    font-weight: var(--instui-component-text-content-small-font-weight);
    line-height: var(--instui-component-text-content-small-line-height);
  }

  &.-variant-content-important {
    font-size: var(--instui-component-text-content-important-font-size);
    line-height: var(--instui-component-text-content-important-line-height);
    font-weight: var(--instui-component-text-content-important-font-weight);
  }

  &.-variant-content-quote {
    font-size: var(--instui-component-text-content-quote-font-size);
    font-weight: var(--instui-component-text-content-quote-font-weight);
    font-style: var(--instui-component-text-content-quote-font-style);
    line-height: var(--instui-component-text-content-quote-line-height);
  }

  &.-variant-legend {
    font-size: var(--instui-component-text-legend-font-size);
    line-height: var(--instui-component-text-legend-line-height);
    font-weight: var(--instui-component-text-legend-font-weight);
  }

  &.-transform-uppercase {
    text-transform: uppercase;
  }

  &.-transform-lowercase {
    text-transform: lowercase;
  }

  &.-transform-capitalize {
    text-transform: capitalize;
  }
}

