    label: string;
    rebrand: string;
    canvas: string;
    canvasHighContrast: string;
    colorLabel?: string;
    navy?: string;
    blue?: string;
    green?: string;
    red?: string;
    orange?: string;
    grey?: string;
    ash?: string;
    plum?: string;
    violet?: string;
    stone?: string;
    sky?: string;
    honey?: string;
