    utilities: string;
    gettingStarted: string;
    architecture: string;
    components: string;
    cdn: string;
    cdnPicker: string;
    registry: string;
    agentTools: string;
    canvasRce: string;
    cli: string;
    plugins: string;
    generated: string;
    api: string;
    css: string;
    apiGroups: {
      ai: string;
      bundlers: string;
      design: string;
      formats: string;
      packages: string;
      platforms: string;
      plugins: string;
      renderers: string;
      tools: string;
    };
    apiOverview: string;
  };
  editText: string;
  // Screen-reader label for the hero's rotating `.platform` pill, which otherwise only announces
  // whichever platform name is currently cycling in (see theme/components/VPHomeHero.vue).
  platformPicker: { label: string };
  // View tabs on the `@pantoken/demo` runner, passed into its iframe by the markdown-it plugin.
