type Engine = { violations: number; reviews: number; reviewRules: Counts; violationRules: Counts };

/** Aggregated result counts for one named check in one tier of one target. */
export interface CheckDetail {
  tier: string;
  name: string;
  criteria: string[];
  counts: Counts;
}

