export interface AccessibilityEvidence {
  target: string;
  theme: string;
  scheme: string;
  source: "page" | "npm";
  run: string;
  date: string;
  tools: Record<string, string>;
  digest: string;
  configurations: number;
  tiers: Record<string, Counts>;
  axe: Engine;
  ibm: Engine;
  checks: Record<string, Counts>;
