  if (!Object.keys(records).length) throw new Error("No supported accessibility evidence");
  return {
    schema: 1,
    records: Object.fromEntries(Object.entries(records).sort(([a], [b]) => a.localeCompare(b))),
  };
}

function cell(value: string): string {
  return value
    .replace(/[\\[\]()*_!#~]/gu, "\\$&")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("|", "&#124;")
    .replaceAll("`", "&#96;")
    .replaceAll("\n", " ");
