  expect(() => loadAccessibilitySnapshot({ schema: 1, records: null })).toThrow("object");
  const row = value.records.button![0]!;
  for (const patch of [
    { flags: -1 },
    { flags: 1.5 },
    { source: "guessed" },
    { theme: "canvas", scheme: "dark" },
