/* Home styles */

:root:has(.is-home) {
  /* Fallback paint for any area outside body during initial layout. */
  background-color: var(--vp-home-bg-color, #002b4d);
}

.is-home {
  /* VitePress sets body background-color from --vp-c-bg in a base layer.
     Override the token on home so that layered rule resolves transparent. */
  --vp-c-bg: transparent;
  position: relative;
  min-height: 100vh;
  background-color: transparent;
}

.is-home::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--vp-home-bg-image);
  background-repeat: no-repeat;
  background-size: cover;
  background-position: right bottom;
  pointer-events: none;
}

html[dir="rtl"] .is-home::before {
  transform: scaleX(-1);
}

.VPNavBar.home {
  background-color: var(--vp-nav-bg-color);
}

/* In RTL layouts, navbar flyouts (language dropdown, extra/theme picker, etc.) sit on the left side
   of the header. VitePress defaults flyout menus to `right: 0`, which aligns their right edge to the
   icon and causes the menu to overflow off the left edge of the page. Align to the left rail instead. */
html[dir="rtl"] .VPFlyout .menu {
  right: auto;
  left: 0;
}

@media (min-width: 768px) {
  html[dir="rtl"] .VPNavBarSearch {
    padding-right: 24px;
    padding-left: 0;
  }
}

@media (min-width: 960px) {
  html[dir="rtl"] .VPNavBarSearch {
    padding-right: 32px;
    padding-left: 0;
  }

  html[dir="rtl"] .VPSidebar {
    right: 0;
    left: auto;
  }

  html[dir="rtl"] .VPContent.has-sidebar {
    padding-right: var(--vp-sidebar-width);
    padding-left: 0;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .title {
    right: 0;
    left: auto;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .content {
    padding-right: var(--vp-sidebar-width);
    padding-left: 32px;
  }

  html[dir="rtl"] .VPNavBar:not(.home.top) .content-body {
    margin-right: 0;
    margin-left: -100vw;
    padding-right: 0;
    padding-left: 100vw;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .divider {
    padding-right: var(--vp-sidebar-width);
    padding-left: 0;
  }
}

@media (min-width: 1280px) {
  html[dir="rtl"] .VPDoc .aside {
    order: 2;
    padding-right: 32px;
    padding-left: 0;
  }

  html[dir="rtl"] .VPDoc .content {
    order: 1;
  }

  html[dir="rtl"] .VPNavBar .content-body .social-links {
    margin-right: 0;
    margin-left: -8px;
  }
}

@media (min-width: 1440px) {
  html[dir="rtl"] .VPSidebar {
    padding-right: max(32px, calc((100% - (var(--vp-layout-max-width) - 64px)) / 2));
    padding-left: 32px;
  }

  html[dir="rtl"] .VPContent.has-sidebar {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: calc((100% - var(--vp-layout-max-width)) / 2);
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .title {
    padding-right: max(32px, calc((100% - (var(--vp-layout-max-width) - 64px)) / 2));
    padding-left: 32px;
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .content {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: calc((100% - var(--vp-layout-max-width)) / 2 + 32px);
  }

  html[dir="rtl"] .VPNavBar.has-sidebar .divider {
    padding-right: calc((100% - var(--vp-layout-max-width)) / 2 + var(--vp-sidebar-width));
    padding-left: 0;
  }
}

/* Class names like `.--bg-<name>` are all bidi-neutral characters, so in an RTL paragraph the bidi
   algorithm gives them the paragraph direction and reorders them on screen. Isolate code as LTR. */
html[dir="rtl"] .vp-doc :is(code, kbd, samp) {
  direction: ltr;
  unicode-bidi: isolate;
}

html[dir="rtl"] .vp-doc div[class*="language-"] :is(pre, code) {
  direction: ltr;
  text-align: left;
}

/* Shared popover chrome for the home hero: both the terminal's package-manager popover
   (CommandCycleRow.vue's `.gs-command-row__popover`) and the platform picker below apply this
   class, so there's one visual treatment instead of two — the hero is on-color in every site
   theme, but that's `light-dark()`'d here exactly like the terminal's own popover already was. */
.hero-popover {
  display: flex;
  flex-direction: column;
  min-inline-size: 10rem;
  padding: 4px;
  border: 1px solid var(--vp-c-divider);
  border-radius: 6px;
  background: light-dark(
    var(--instui-color-background-container),
    var(--instui-color-background-page)
  );
  box-shadow: 0 2px 8px rgb(0 0 0 / 26%);
}

.hero-popover button {
  padding: 4px 8px;
  border: 0;
  border-radius: 4px;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
  /* Without this, the browser's default focus/active ring (which picks up `currentColor`, i.e.
     each item's brand color) flashes briefly on mouseleave between hover and focus-visible states. */
  outline: none;
}

.hero-popover button:hover,
.hero-popover button:focus-visible {
  background: light-dark(#e9edf3, #2a3038);
  outline: none;
}

.VPHomeHero {
  .heading {
    color: var(--instui-primitive-color-white);

    & :is(.name, .clip) {
      color: var(--vp-home-hero-name-color, var(--instui-primitive-color-blue-blue50));
      -webkit-text-fill-color: var(
        --vp-home-hero-name-color,
        var(--instui-primitive-color-blue-blue50)
      );
    }
  }

  .tagline {
    /* color: #aab0b5; */
    display: none;
  }

  .platform {
    position: relative;
    display: inline-flex;
    align-items: center;
    background-color: color-mix(
      in srgb,
      var(--instui-color-institutional-brand-primary) 50%,
      transparent
    );
    box-shadow: inset 0 -4px 0 0
      color-mix(in srgb, var(--instui-color-institutional-brand-primary) 75%, transparent);
    padding: 0 0.25rem;
    border-radius: var(--instui-primitive-size-size4);
    cursor: pointer;
  }

  .platform:hover {
    box-shadow:
      inset 0 -4px 0 0
        color-mix(in srgb, var(--instui-color-institutional-brand-primary) 75%, transparent),
      0 0 0 2px rgba(255, 255, 255, 0.5);
  }

  /* Keyboard-focus-only affordance hinting the pill opens a picker — collapsed to zero width
     otherwise, so it never nudges the pill's layout or shows on mouse hover. */
  .platform-picker__chevron {
    display: inline-block;
    inline-size: 0;
    block-size: 0.5em;
    margin-inline-start: 0;
    overflow: hidden;
    opacity: 0;
    border-inline-end: 2px solid currentColor;
    border-block-end: 2px solid currentColor;
    transform: rotate(45deg) translateY(-2px);
    transition:
      opacity 0.15s ease,
      inline-size 0.15s ease,
      margin-inline-start 0.15s ease;
  }

  .platform:focus-visible .platform-picker__chevron {
    inline-size: 0.5em;
    margin-inline-start: 0.3em;
    opacity: 0.8;
  }

  /* Position/sizing/grouping only — visual chrome (background, border, shadow, button hover) comes
     from the shared `.hero-popover` class above. */
  .platform-picker__menu {
    position: absolute;
    inset-block-start: calc(100% + 8px);
    inset-inline-start: 0;
    z-index: 20;
    display: none;
    gap: 2px;
    min-inline-size: 12rem;
    max-block-size: 22rem;
    overflow-y: auto;
    font-size: 0.85rem;
    font-weight: 400;
    /* `.heading`/`.text` set a fixed-px line-height (40-64px across breakpoints); that's an
       inherited absolute length, so it doesn't shrink with the smaller font-size above and would
       otherwise make every row enormous. */
    line-height: 1.3;
    text-transform: none;
    letter-spacing: normal;
    cursor: auto;
  }

  .platform-picker__menu.-open {
    display: flex;
  }

  .platform-picker__group-title {
    padding: 2px 6px;
    color: var(--vp-c-text-2);
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .platform-picker__menu [role="group"] {
    display: flex;
    flex-direction: column;
  }

  .platform-picker__menu button {
    display: flex;
    align-items: center;
    gap: 0.4em;
    padding: 3px 6px;
  }

  .platform-picker__icon {
    display: inline-block;
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
    mask: var(--pantoken-glyph) center / contain no-repeat;
  }

  /* Keeps the animated platform label on one line even when the roller swaps in a long label like
      "WordPress". */
  .platform-line {
    white-space: nowrap;
  }

  /* "accessible WordPress" is close to the line's available width on narrow phones; shrink slightly
     so it doesn't spill past the hero's edge padding. */
  @media (max-width: 639px) {
    .platform-line {
      font-size: 0.85em;
    }
  }

  /* Text roller built by VPHomeHero.vue's platform cycle: a fixed-height clipping window holding one
     or two absolutely positioned `.platform-label`s, so the outgoing label can slide down out of
     view while the incoming one slides up into its place. `.platform`'s own width is auto and
     tracks the viewport's animated width every frame, since inline-block children size their
     container just like plain text would. */
  .platform-viewport {
    position: relative;
    display: inline-block;
    overflow: hidden;
    height: 1.2em;
    transition: width 0.45s ease;
  }

  .platform-label {
    position: absolute;
    inset-inline-start: 0;
    top: 0;
    display: inline-block;
    white-space: nowrap;
    transition: transform 0.45s ease;
  }

  /* Same roller technique as `.platform-viewport`/`.platform-label`, but for the brand glyph:
     `--pantoken-glyph` is set inline per glyph element (not via a platform class) so the outgoing
     and incoming glyphs can each keep their own icon while they slide past one another.
     Named `.platform-glyph*`, not `.platform-icon*` — any class containing the substring
     "-icon-" gets painted by the design system's generic `[class*="-icon-"]::before` painter,
     which would render a second, broken glyph on top of this one. */
  .platform-glyph-viewport {
    position: relative;
    display: inline-block;
    overflow: hidden;
    inline-size: 0.75em;
    block-size: 0.75em;
    margin-inline-end: 0.0625em;
    margin-bottom: 0.125em;
  }

  .platform-glyph {
    position: absolute;
    inset-inline-start: 0;
    top: 0;
    inline-size: 100%;
    block-size: 100%;
    background: currentColor;
    -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
    mask: var(--pantoken-glyph) center / contain no-repeat;
    transition: transform 0.45s ease;
  }
}

.VPHomeFeatures .box:has(.VPImage) {
  grid-template-columns: 1.25rem 1fr;
  align-items: start;
  gap: 0.5rem 0.75rem;
  display: grid;

  .VPImage {
    grid-area: 1/1;
    width: 1.25rem;
    margin: 0;
  }

  .details {
    grid-column: 1/-1;
    margin: 0;

    :not(pre) > code {
      color: var(--vp-code-color);
      background: var(--vp-code-bg);
      border-radius: 4px;
      padding: 3px 6px;
      font-size: var(--vp-code-font-size);
    }

    a {
      color: var(--instui-color-text-interactive-navigation-primary-base);
      text-decoration: underline;

      &:hover,
      &:focus-visible,
      &:active {
        color: var(--instui-color-text-interactive-navigation-primary-hover);
      }
    }
  }
}

.vitepress-sidebar-toggle {
  margin-inline-start: 2rem;
}

/* The light/dark toggle now lives inside ThemeColorPicker (desktop dropdown, tablet kebab, mobile
   accordion) so it travels with the theme/color choice — hide VitePress's standalone copies.
   `!important` because VitePress's own scoped style (with its `[data-v-*]` attribute selector) 
   otherwise outweighs our plain class selector. */
.VPNavBarAppearance,
.VPNavScreenAppearance {
  display: none !important;
}

/* Keep custom outline social icons from inheriting VitePress's solid icon fill. */
.VPSocialLink > svg {
  fill: none !important;
}

/* VitePress rounds and scrolls `.VPMenu` on the same box; the translations flyout lists 40+ locales,
   so its native scrollbar routinely squares off the corners it touches. Move the radius + shadow to
   the flyout's outer `.menu` wrapper and clip through `overflow: hidden` there instead, leaving
   `.VPMenu` to scroll unconstrained by rounding. */
.VPNavBarTranslations .menu {
  overflow: hidden;
  border-radius: 12px;
  box-shadow: var(--vp-shadow-3);
  border: 1px solid var(--vp-c-divider);
}

.VPNavBarTranslations .menu .VPMenu {
  border-radius: 0;
  box-shadow: none;
  border: 0 none;
}

@media (min-width: 768px) {
  .VPNavBarTranslations .menu,
  .VPNavBarTranslations .menu .VPMenu {
    max-height: 50vh;
  }

  .VPNavBarSearchButton.VPNavBarSearchButton {
    background-color: light-dark(var(--instui-primitive-color-grey-grey10), var(--vp-c-bg-alt));
  }
}

@media (min-width: 960px) {
  .VPNavBarTitle.has-sidebar .title {
    --vp-c-divider: transparent;
  }
}

.custom-block {
  border-width: 2px;
  box-shadow: var(--instui-elevation-above);

  &.tip {
    background-color: transparent;
    border-color: var(--vp-custom-block-tip-bg);

    code {
      background: transparent;
    }
  }

  &.warning {
    background-color: transparent;
    border-color: var(--vp-custom-block-warning-bg);

    code {
      background: transparent;
    }
  }

  &.info {
    background-color: transparent;
    border-color: var(--vp-custom-block-info-bg);

    code {
      background: transparent;
    }
  }

  &.danger {
    background-color: transparent;
    border-color: var(--vp-custom-block-danger-bg);

    code {
      background: transparent;
    }
  }
}

before.content:
/* Use InstUI's font, Atkinson Hyperlegible Next (from @pantoken/components/fonts.css), for the
   whole site. The token carries its own fallback chain: Atkinson, then system-ui. */
/* Brand glyphs for the hero tagline's chained `.platform.<name>` pills (e.g. `.web` → HTML5), cycled
   by `VPHomeHero.vue`'s platform animation — one per emitted platform/renderer/bundler format. */
@import "@pantoken/plugin-simple-icons/icons/html5.css";
@import "@pantoken/plugin-simple-icons/icons/react.css";
@import "@pantoken/plugin-simple-icons/icons/vuedotjs.css";
@import "@pantoken/plugin-simple-icons/icons/swift.css";
@import "@pantoken/plugin-simple-icons/icons/android.css";
@import "@pantoken/plugin-simple-icons/icons/wordpress.css";
@import "@pantoken/plugin-simple-icons/icons/angular.css";
@import "@pantoken/plugin-simple-icons/icons/svelte.css";
@import "@pantoken/plugin-simple-icons/icons/astro.css";
@import "@pantoken/plugin-simple-icons/icons/vite.css";
@import "@pantoken/plugin-simple-icons/icons/webpack.css";
@import "@pantoken/plugin-simple-icons/icons/tailwindcss.css";
@import "@pantoken/plugin-simple-icons/icons/postcss.css";
@import "@pantoken/plugin-simple-icons/icons/nextdotjs.css";
@import "@pantoken/plugin-simple-icons/icons/jetpackcompose.css";
@import "@pantoken/plugin-simple-icons/icons/flutter.css";
@import "@pantoken/plugin-simple-icons/icons/rust.css";
@import "@pantoken/plugin-simple-icons/icons/drupal.css";
@import "@pantoken/plugin-simple-icons/icons/hugo.css";
@import "@pantoken/plugin-simple-icons/icons/jekyll.css";
@import "@pantoken/plugin-simple-icons/icons/sass.css";
@import "@pantoken/plugin-simple-icons/icons/stylus.css";
@import "@pantoken/plugin-simple-icons/icons/storybook.css";
@import "@pantoken/plugin-simple-icons/icons/bootstrap.css";
@import "@pantoken/plugin-simple-icons/icons/docusaurus.css";
@import "@pantoken/plugin-simple-icons/icons/mintlify.css";
@import "@pantoken/plugin-simple-icons/icons/shadcnui.css";
@import "@pantoken/plugin-simple-icons/icons/webcomponentsdotorg.css";
@import "@pantoken/plugin-simple-icons/icons/mui.css";
@import "@pantoken/plugin-custom-icons/icons/zurb.css";
@import "@pantoken/plugin-custom-icons/icons/tiny.css";
@import "@pantoken/plugin-custom-icons/icons/figma.css";

:root {
  /* Vite's production CSS transform lowers light-dark() to scheme helper variables. Give that
     transform an explicit light default to pair with the dark override below; without it,
     both lowered branches remain active in light mode and concatenate into invalid colours. */
  color-scheme: light;

  --vp-c-bg: var(--instui-color-background-container);
  --vp-local-nav-bg-color: var(--instui-color-background-container);
  --vp-sidebar-bg-color: var(--instui-color-background-muted);

  /* Component tokens (tab underlines, badges, menu active states, the calendar's "today") read this
     directly, bypassing the --vp-c-brand-* bridge in @pantoken/vitepress entirely — the rebrand theme
     ships it as navy by default, a different blue than --vp-c-brand-1 resolves to. Point it at the same
     source so InstUI's own brand-colored chrome and VitePress's brand-driven UI read as one color.
     `:root[data-pantoken-theme]` scoping still wins on specificity, so canvas/canvas-high-contrast keep
     their own values untouched. */
  --instui-color-institutional-brand-primary: var(
    --instui-color-text-interactive-navigation-primary-base
  );
}

html.dark {
  --vp-c-bg: var(--instui-color-background-page);
  --vp-local-nav-bg-color: var(--instui-color-background-page);
  --vp-sidebar-bg-color: var(--instui-color-background-container);
  color-scheme: dark;
}

@media (min-width: 90rem) {
  .VPContent.has-sidebar:has(.VPPage) {
    padding-right: 0;
  }
}

.sidebar-hidden {
  --vp-sidebar-width: 0;
}

.VPSidebarItem .text::first-letter {
  text-transform: capitalize;
}

.VPSidebarItem.level-0.level-0 {
  padding-bottom: 0.625rem;
}

.VPSidebarItem.level-0
  > .items
  > li
  > .VPSidebarItem.level-1.is-link:only-child
  > .item
  > .link
  > .text {
  font-weight: 700 !important;
}

/* Each CSS-API `@example` is a source fence that seams into a bordered, page-background frame
   (`.css-example`, now an isolated `<iframe srcdoc>` — see `@pantoken/demo`'s `buildExampleSrcdoc` —
   so nothing from `.vp-doc` leaks into the live preview), wrapped in `.css-example-frame` (the actual
   sibling of the fence, so the button below can overlay the iframe) — the fence loses its bottom
   rounding + margin so the two read as one unit (square BOTH the frame and the inner <pre>, which
   paints the dark bg + carries its own radius, so no rounded corner peeks through the seam). Inside the
   frame, the live example sits in the same elevated `.instui-card` the /demos use (from
   `@pantoken/demo/card.css`, loaded inside the iframe itself). */
div[class*="language-"]:has(+ .css-example-frame) {
  margin-bottom: 0;
}

div[class*="language-"]:has(+ .css-example-frame),
div[class*="language-"]:has(+ .css-example-frame) > pre {
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  max-height: 21rem;
}

.css-example-frame {
  position: relative;
  display: block;
}

.css-example {
  display: block;
  width: 100%;
  /* A sane floor before the iframe's `pantoken-demo-size` postMessage arrives and sets an inline height. */
  min-height: 4rem;
  border: 1px solid var(--vp-c-divider);
  border-block-start: 0;
  border-end-start-radius: 8px;
  border-end-end-radius: 8px;
  margin: 0 0 16px;
  /* Match the page background (like the demo frame), so only the inner .instui-card reads as elevated. */
  background: var(--instui-color-background-page);
}

/* Reveal-on-hover corner button: base appearance ships with `@pantoken/demo/demo.css` (also used by
   `/play`'s `.pantoken-demo` figure); this just adds the extra hover trigger for the CSS-API wrapper. */
.css-example-frame:hover .pantoken-demo__fullscreen,
.pantoken-demo__fullscreen:focus-visible {
  opacity: 1;
}

/* Stylize prompts */

/* VitePress makes code blocks full-bleed (negative margins, no radius) on narrow viewports; keep the
   paired example fence contained so it stays aligned with the frame below it. */
@media (max-width: 639px) {
  .vp-doc div[class*="language-"]:has(+ .css-example-frame) {
    margin-inline: 0;
    border-radius: 8px 8px 0 0;
  }
}

.vp-doc div:is(.language-prompt, .language-ai) {
  background:
    linear-gradient(
        to right,
        var(--instui-component-shared-tokens-background-ai-top-gradient-color) 0%,
        var(--instui-component-shared-tokens-background-ai-bottom-gradient-color) 100%
      )
      padding-box,
    linear-gradient(
        to right,
        var(--instui-component-shared-tokens-background-ai-bottom-gradient-color) 0%,
        var(--instui-component-shared-tokens-background-ai-top-gradient-color) 100%
      )
      border-box;

  .lang {
    margin-top: 4px;
  }

  pre {
    border: 0 none;
    border-radius: 4px;
    margin: 4px;
    padding: 20px 0;
    background: var(--vp-code-block-bg);
    white-space: pre-wrap;
    overflow-wrap: anywhere;

    span::selection {
      background: var(--instui-component-text-ai-background-color);
      color: var(--instui-component-text-ai-color);
    }
  }
}

/* Previews for token values in the CSS API tables, dropped below the raw value by the
   `tokenValuePreview` markdown-it plugin. Two kinds: `.pantoken-token-preview` (decoded image SVGs)
   and `.pantoken-swatch` (colour chips). */

/* Image-valued tokens (icons, logos, mask helpers) carry a `data:image` URI; the plugin decodes it to
   inline SVG here. The box carries `color: var(--vp-c-text-1)` so `currentColor` icons resolve to the
   theme text colour and stay visible in light and dark; the SVG is capped so wide logos don't overflow
   the table cell. */
.pantoken-token-preview {
  display: inline-block;
  margin-right: 8px;
  margin-bottom: 0;
  line-height: 0;
}

.pantoken-token-preview :is(svg, img) {
  width: auto;
  height: auto;
  max-width: 100%;
  max-height: 3rem;
}

/* Colour swatches: a single chip for one colour, or two labelled chips (Light/Dark) for a
   `light-dark()` value — both branches shown at once, no theme toggle needed. Each chip sits over a
   theme-neutral checkerboard so translucent colours (e.g. `#00000000`) read as translucent. */
.pantoken-swatch {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: last baseline;
  margin-right: 0.5rem;
}

.pantoken-swatch__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.pantoken-swatch__chip {
  inline-size: 1.25rem;
  block-size: 1.25rem;
  border: 1px solid var(--vp-c-divider);
  border-radius: 4px;
  overflow: hidden;
  /* A small grey checkerboard, painted behind each fill so alpha shows through. */
  background-color: #fff;
  background-image:
    linear-gradient(45deg, #c8ccd0 25%, transparent 25%, transparent 75%, #c8ccd0 75%),
    linear-gradient(45deg, #c8ccd0 25%, transparent 25%, transparent 75%, #c8ccd0 75%);
  background-size: 8px 8px;
  background-position:
    0 0,
    4px 4px;
}

.pantoken-swatch__fill {
  display: block;
  inline-size: 100%;
  block-size: 100%;
}

.pantoken-swatch__label {
  font-size: 12px;
  color: var(--vp-c-text-2);
}

/* Deprecation markers in the CSS API reference. `@cssdoc`'s `classNames.deprecated` hook wraps just the
   word "Deprecated" (in the `> [!WARNING]` banner and each deprecated modifier-table cell) in an
   `instui-pill` warning tag, leaving the reason prose beside it. It's a compact label, so it renders as
   the shipped pill directly — this docs-only `.pantoken-doc-tag` only centers it against the adjacent
   prose. Scoped to `.pantoken-doc-tag`, so real `.instui-pill` previews in a `.css-example` are untouched. */
.vp-doc .instui-pill.pantoken-doc-tag {
  vertical-align: middle;
  white-space: nowrap;
}

/* Accessibility audit tables: the check name may wrap anywhere; its WCAG criteria sit on their own line. */
.vp-doc .pantoken-a11y-check,
.vp-doc .pantoken-a11y-criteria {
  display: block;
}

.vp-doc .pantoken-a11y-check {
  overflow-wrap: anywhere;
}

.vp-doc .pantoken-a11y-criteria {
  font-size: 0.875em;
  opacity: 0.8;
}

.vp-doc table.pantoken-a11y-table th[scope="row"] {
  text-align: start;
  vertical-align: top;
}

.vp-doc table.pantoken-a11y-table td {
  vertical-align: middle;
}

/* The explanation row spans every theme column and reads as a note on the row above it. */
.vp-doc table.pantoken-a11y-table td.pantoken-a11y-details {
  font-size: 0.875em;
}

.vp-doc table.pantoken-a11y-table td.pantoken-a11y-details p {
  margin: 0;
}

.vp-doc table.pantoken-a11y-table td.pantoken-a11y-details p + p {
  margin-block-start: 0.5em;
}

/* `@interaction` modifier markers in CSS API tables use the same badge treatment as deprecated/alias,
   but with an interaction-specific violet accent text colour. */
.vp-doc .instui-pill.pantoken-doc-tag.pantoken-doc-tag-interaction {
  color: var(--instui-color-text-accent-violet);
  border-color: var(--instui-color-text-accent-violet);
}

/* In docs tables, prevent wrap overlap where description prose mixes pills + inline code.
   Scope to the last cell only (the description-style column in API/guide tables), and only style
   the inline badge/code elements — nothing outside table cells is affected. */
.vp-doc
  table
  td:last-child:has(.instui-pill.pantoken-doc-tag, code)
  :is(.instui-pill.pantoken-doc-tag, code) {
  line-height: 1.5rem;
}

/* Header logo dot color overlay reflecting active theme color choice. The wordmark SVG is loaded via
   `<img>`, so it can't pick up page CSS (no `currentColor`/`var()` inside an external image document) —
   this pseudo-element paints the dot instead, masked to the dot's own circle. VitePress's own
   `.title { width: 100% }` stretches to fill the nav bar (not just the logo), so the overlay can't be
   sized off `.title`'s box — it's sized off the logo `<img>`'s own box instead: `height: 24px` (set
   below) times each wordmark's own aspect ratio. VitePress's default `.logo` also carries a *physical*
   `margin-right: 8px` that doesn't flip for `dir="rtl"`, so the image's physical right edge always sits
   8px in from `.title`'s right edge in both directions — matched here with physical `left`/`right`
   (not logical `inset-inline-*`, which would assume the image is flush to the logical start edge and
   misplace it under RTL). Every locale with a script-specific wordmark (see `NON_LATIN_LOCALES` in
   `i18n.ts`) has its own aspect ratio and draws its dot at a different position in a
   differently-proportioned viewBox, so `--pantoken-logo-mask` and `--pantoken-logo-aspect` are set per
   `html[lang]` below. */
.VPNavBarTitle .title {
  position: relative;
  display: inline-flex;
  align-items: center;
  --pantoken-logo-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27108.948%20121.056%20696.252%20123.284%27%3E%3Ccircle%20cx%3D%27787.3%27%20cy%3D%27225.5%27%20r%3D%2713.9%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E");
  --pantoken-logo-aspect: 5.647546;
}

.VPNavBarTitle .logo {
  height: 24px;
  width: auto;
  transition: opacity 0.25s;
}

.VPNavBarTitle .title::after {
  content: "";
  position: absolute;
  left: 0;
  top: calc(50% - 12px);
  width: calc(24px * var(--pantoken-logo-aspect));
  height: 24px;
  background-color: var(--pantoken-logo-dot-color);
  -webkit-mask: var(--pantoken-logo-mask) no-repeat center / contain;
  mask: var(--pantoken-logo-mask) no-repeat center / contain;
  pointer-events: none;
}

html[dir="rtl"] .VPNavBarTitle .title::after {
  left: auto;
  right: 8px;
}

html[lang="el"] .VPNavBarTitle .title {
  --pantoken-logo-mask: url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%27-0.344%20-117.572%20736.274%20123.400%27%3E%3Ccircle%20cx%3D%27717.651%27%20cy%3D%27-12.843%27%20r%3D%2714.279%27%20fill%3D%27black%27%2F%3E%3C%2Fsvg%3E");
