test.each(["success", "pack failure", "fixture gap", "no archetype", "full inventory"])(
  "appends npm evidence: %s",
  async (outcome) => {
    const root = temp();
    for (const folder of [
      "pages/assets/tokens",
      "pages/assets/components",
      "pages/assets/interactions",
    ])
      mkdirSync(join(root, folder), { recursive: true });
    for (const file of [
