      .map(
        ([names, w]) =>
          `@media (max-width: ${w}) { ${selectors(p, "hidden-max-", names)} { display: none !important; } }\n` +
          `@media (min-width: ${w}) { ${selectors(p, "hidden-min-", names)} { display: none !important; } }`,
      )
      .join("\n");
