      .map(
        ([names, w]) =>
          `@media (max-width: ${w}) { ${selectors(p, "show-max-", names)} { display: revert !important; } }\n` +
          `@media (min-width: ${w}) { ${selectors(p, "show-min-", names)} { display: revert !important; } }`,
      )
      .join("\n");
