 * </div>
 */
.-with-visual-debug {
  outline: 0.0625rem solid var(--pantoken-visual-debug-color, #f42272);
}

.-with-visual-debug > * {
  outline: 0.0625rem dashed var(--pantoken-visual-debug-color, #f42272);
}

