const total = (key: string): number => counts.reduce((sum, item) => sum + (item[key] ?? 0), 0);
  if (total("fail")) return "fail";
  if (total("undetermined")) return "review";
  if (total("pass")) return "pass";
  return total("not-applicable") ? "na" : "review";
}

/** Escape text for a raw HTML block: markdown escapes would show literally, and `{` would reach Vue. */
function html(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("{", "&#123;")
    .replaceAll("}", "&#125;");
}
  const all = groups.size === 1 && [...groups.values()][0]!.columns.length === AUDIT_MATRIX.length;
  const body = [...groups.values()]
    .map(({ columns, note, elements: list }) => {
      const label = all
        ? ""
        : `<strong>${columns
            .map((i) => html(columnLabel(AUDIT_MATRIX[i]!.theme, AUDIT_MATRIX[i]!.scheme)))
            .join(", ")}:</strong> `;
      const items = list.length
        ? `<ul>${list.map((item) => `<li><code>${html(item)}</code></li>`).join("")}</ul>`
        : "";
      return `<p>${label}${html(note)}</p>${items}`;
    })
    .join("");
