const VISUAL = /^-?-?(color|size|variant|state|status|type|tone|level|shape|border|elevation|shadow|disabled|readonly|invalid|error|checked|selected|active|current|loading|indeterminate|inverse|on-color|focus|hover|expanded|open|bordered|ai|primary|secondary|danger|success|warning|info|brand)/;
let totalMiss = 0, totalVis = 0;
