import { parseCssDocs } from "@cssdoc/core";
import { resolveExampleTargets } from "@pantoken/utils/example-targets";
import { auditRecords } from "./audit-plugin-components.ts";
const VISUAL = /^-?-?(color|size|variant|state|status|type|tone|level|shape|border|elevation|shadow|disabled|readonly|invalid|error|checked|selected|active|current|loading|indeterminate|inverse|on-color|focus|hover|expanded|open|bordered|ai|primary|secondary|danger|success|warning|info|brand)/;
let totalMiss = 0, totalVis = 0;
const rows: string[] = [];
for (const r of auditRecords()) {
  const e = parseCssDocs(r.rules("instui-")).find((c) => c.name === r.name)! as any;
  const html = resolveExampleTargets(e.examples).automatica11y.map((i: number) => e.examples[i]).join("\n");
  const mods: string[] = (e.modifiers ?? []).map((m: any) => String(m.name ?? m.selector ?? m));
  const vis = mods.filter((m) => VISUAL.test(m.replace(/^\./, "")));
  const missing = vis.filter((m) => !html.includes(m.replace(/^\./, "")));
  totalVis += vis.length; totalMiss += missing.length;
  rows.push(`${r.name}\tvisual=${vis.length}\tmissing=${missing.length}\t${missing.slice(0, 6).join(" ")}`);
}
console.log(rows.join("\n"));
console.log(`TOTAL visual=${totalVis} missing=${totalMiss}`);
