/**
 * @component skeleton-loader
 * @summary Decorative placeholder for content that has not loaded yet.
 * @selector .pfx-skeleton-loader
 * @modifier -type-text — A text bar (default).
 * @modifier -type-avatar — A round avatar placeholder, medium size only.
 * @modifier -type-image — An image placeholder, medium size only.
 * @modifier -size-xxs — Legend-sized text row.
 * @modifier -size-xs — Extra-small text row.
 * @modifier -size-sm — Small text row.
 * @modifier -size-md — Medium text row (default).
 * @modifier -size-lg — Large text row.
 * @modifier -size-xl — Extra-large text row.
 * @modifier -size-xxl — Largest text row.
 * @part .shape — The clipped placeholder surface sized for the selected loader type.
 * @part .skeleton-row — A repeated text-row wrapper that applies vertical spacing.
 * @structure
 * .pfx-skeleton-loader {
 *   .shape {}
 *   .skeleton-row:many {
 *     .shape {}
 *   }
 * }
 * @a11y Mark the decorative loader aria-hidden="true". Put aria-busy on the parent content region,
 *   with an initially empty status and alert outside that region. Use initSkeletonLoading from the
 *   interactions package to announce the parent's loading state. Shapes must not receive focus.
 * @example
 * ```html
 * <div style="display: flex; align-items: center; gap: 1rem; max-inline-size: 24rem">
 *   <div class="pfx-skeleton-loader -type-avatar" aria-hidden="true">
 *     <div class="shape"></div>
 *   </div>
 *   <div style="flex: 1">
 *     <div class="pfx-skeleton-loader -type-text -size-md" aria-hidden="true">
 *       <div class="skeleton-row" style="inline-size: 45%"><div class="shape"></div></div>
 *       <div class="skeleton-row" style="inline-size: 72%"><div class="shape"></div></div>
 *     </div>
 *   </div>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <section aria-label="Profile details" aria-busy="true" data-a11y-root>
 *   <div class="pfx-skeleton-loader -type-text" aria-hidden="true">
 *     <div class="skeleton-row"><div class="shape"></div></div>
 *     <div class="skeleton-row"><div class="shape"></div></div>
 *   </div>
 * </section>
 * <p role="status" aria-live="polite"></p>
 * ```
 */
