/**
 * @utility logo
 * @selector .pfx-logo
 * @summary The logo system preserves each product logo's colors and aspect ratio. Explicit current-color variants inherit the text color.
 * @global
 * @modifier -logo-* — Set the glyph token (`--pantoken-glyph`) and its aspect ratio (`--pantoken-logo-aspect`), then render both via the shared painter (for example `-logo-canvas-horizontal-color`, from `@pantoken/plugin-logos`).
 * @a11y A logo is meaningful, not decorative — give the host element `role="img"` and an `aria-label` naming the product; never mark it `aria-hidden`.
 * @example
 * <span class="instui-logo -logo-canvas-horizontal-color" role="img" aria-label="Canvas logo"></span>
 * @example -automatica11y
 * ```html
 * <span class="pfx-logo -logo-canvas-horizontal-color" role="img" aria-label="Canvas logo" data-a11y-root></span>
 * ```
 */
@scope (.pfx-logo) {
  & {
    display: inline-flex;
  }
}

[class*="-logo-"]::before {
  content: "";
  display: inline-block;
  inline-size: 8em;
  aspect-ratio: var(--pantoken-logo-aspect, 1);
  block-size: auto;
  flex: none;
  vertical-align: -0.125em;
  background: var(--pantoken-logo-fill, transparent);
  background-image: var(--pantoken-logo-image, var(--pantoken-glyph));
  background-position: center;
  background-size: contain;
  background-repeat: no-repeat;
  -webkit-mask: var(--pantoken-logo-mask, none) center / contain no-repeat;
  mask: var(--pantoken-logo-mask, none) center / contain no-repeat;
}

