/**
 * @component banner
 * @summary A dismissible, iconed message surface for page-level or in-context announcements.
 * @remarks
 *   **Size** controls padding and gap: `relaxed` (default) is roomier; `compact` tightens both.
 *   **Color** sets the fill: bare (no modifier) is unfilled — border and icon only; `-color-violet`
 *   and `-color-sea` add a tinted background plus a matching icon swatch.
 * @selector .pfx-banner
 * @annotations
 * 1. Banner renders an `info` glyph by default. Add `-icon-<name>` to swap it for any glyph from the shared icon set.
 * 2. The close button follows `alert`'s top-end positioning. It defaults to small; add a size modifier to override it.
 * 3. A heading (`h1`–`h6`, or a bare `.pfx-heading` with no `-level-*` modifier) styles as the
 *    banner's title, using title-card typography appropriate to the active size. Give an
 *    `.pfx-heading` a `-level-*` class to opt it out of this treatment.
 * 4. Wrap banner actions in `.button-group`: buttons before the last default to the inline secondary
 *    treatment, and the last button defaults to the inline primary treatment. Add a `-color-*`
 *    modifier to any button to use its own colour.
 * 5. Buttons default to `-size-sm` regardless of the banner's own size; add a `-size-*` modifier to
 *    opt out.
 * @modifier -size-relaxed — Roomier padding and gap (default).
 * @modifier -size-compact — Tighter padding and gap.
 * @modifier -size-sm - @alias {@link -size-compact}
 * @modifier -size-md - @alias {@link -size-relaxed}
 * @modifier -color-violet — Violet-tinted background and icon swatch.
 * @modifier -color-sea — Sea-tinted background and icon swatch.
 * @modifier -icon-* — Swap the default `info` glyph for an icon from the shared icon set (for example, `-icon-megaphone`).
 * @part button-group — The row container for banner action buttons.
 * @structure
 * .pfx-banner {
 *   @component heading:optional {}
 *   slot {}
 *   @variant bare-button {
 *     @component button:max-1 {}
 *   }
 *   @variant button-group {
 *     .button-group {
 *       @component button:one-or-more:max-2 {}
 *     }
 *   }
 *   @component close-button:optional {}
 * }
 * @a11y Add `role="status"` (or `role="alert"` for urgent messages) so assistive tech announces the
 *   banner; mark a decorative icon `aria-hidden="true"` and give the close button an `aria-label`.
 * @usage @import "@pantoken/plugin-custom-components/custom-components.css";
 * @example -canvas-rce -docs -nocard
 * ```html
 * <div class="pfx-banner -icon-canvas-icon-reversed" role="status">
 *   <h2 class="pfx-heading">New feature</h2>
 *   <span class="instui-text">This is a violet banner with a custom icon.</span>
 *   <div class="button-group">
 *     <button class="pfx-button">Cancel</button>
 *     <button class="pfx-button">OK</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * ```
 * ### Sea colored and compact spacing -nocard
 * ```html
 * <div class="pfx-banner -color-sea -size-sm" role="status">
 *   This is a sea-colored banner with compact spacing.
 * </div>
 * ```
 * @example -canvas-rce-no-interactions -nocard
 * ```html
 * <div class="pfx-banner -icon-canvas-icon-reversed" role="status">
 *   <h2 class="pfx-heading">New feature</h2>
 *   <span class="instui-text">This is a violet banner with a custom icon.</span>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <div class="pfx-banner" role="status" data-a11y-root>
 *   <h2>Profile changes saved</h2>
 *   <span>Your changes are available.</span>
 *   <div class="button-group">
 *     <button class="pfx-button">Undo</button>
 *     <button class="pfx-button">View</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Dismiss notification" data-a11y-trigger></button>
 * </div>
 * <div class="pfx-banner -color-violet -size-relaxed" role="status">
 *   <h2>Violet notification</h2>
 *   <span>Your changes are available.</span>
 *   <button class="pfx-button">View</button>
 * </div>
 * <div class="pfx-banner -color-violet -size-compact" role="status">
 *   <h2>Compact violet notification</h2>
 *   <span>Your changes are available.</span>
 *   <button class="pfx-close-button" aria-label="Dismiss compact violet notification"></button>
 * </div>
 * <div class="pfx-banner -color-sea -size-relaxed" role="status">
 *   <h2>Sea notification</h2>
 *   <span>Your changes are available.</span>
 *   <button class="pfx-close-button" aria-label="Dismiss sea notification"></button>
 * </div>
 * <div class="pfx-banner -color-sea -size-compact" role="status">
 *   <h2>Compact sea notification</h2>
 *   <span>Your changes are available.</span>
 *   <div class="button-group">
 *     <button class="pfx-button">Undo</button>
 *     <button class="pfx-button">View</button>
 *   </div>
 * </div>
 * ```
 * @related alert — A non-dismissible, status-coloured counterpart for inline messages.
 * @related close-button — The dismiss control a banner may include.
 * @todo revisit when the banner tokens land upstream, much of this is hand-roled from figma
 * @alpha
 */
@scope (.pfx-banner) {
  :scope {
    --pantoken-banner-glyph: var(--instui-icon-megaphone);
    --pantoken-banner-icon-background: var(--instui-component-banner-violet-icon-background);
    --pantoken-banner-icon-size: 2rem;
    --pantoken-banner-icon-inset-block-start: var(
      --instui-component-banner-relaxed-padding-vertical
    );
    --pantoken-banner-icon-inset-inline-start: var(
      --instui-component-banner-relaxed-padding-horizontal
    );
    /* @ref 2 */
    --pantoken-banner-close-button-reserve: 0rem;
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--instui-component-banner-content-gap-vertical);
    color: var(--instui-component-banner-color);
    border: var(--instui-component-banner-border-width) var(--instui-component-banner-border-style)
      var(--instui-component-banner-border-color);
    border-radius: var(--instui-component-banner-border-radius);
    padding-block: var(--instui-component-banner-relaxed-padding-vertical);
    padding-inline-start: calc(
      var(--instui-component-banner-relaxed-padding-horizontal) + var(--pantoken-banner-icon-size) +
        var(--instui-component-banner-relaxed-content-gap-horizontal)
    );
    padding-inline-end: calc(
      var(--instui-component-banner-relaxed-padding-horizontal) +
        var(--pantoken-banner-close-button-reserve)
    );
    background: var(--instui-component-banner-violet-background);
    font-size: var(--instui-font-size-text-base);
    line-height: var(--instui-line-height-standalone-text-base);

    &:is(.-size-compact, .-size-sm) {
      --pantoken-banner-icon-size: 1.5rem;
      --pantoken-banner-icon-inset-block-start: var(
        --instui-component-banner-compact-padding-vertical
      );
      --pantoken-banner-icon-inset-inline-start: var(
        --instui-component-banner-compact-padding-horizontal
      );
      padding-block: var(--instui-component-banner-compact-padding-vertical);
      padding-inline-start: calc(
        var(--instui-component-banner-compact-padding-horizontal) +
          var(--pantoken-banner-icon-size) +
          var(--instui-component-banner-compact-content-gap-horizontal)
      );
      padding-inline-end: calc(
        var(--instui-component-banner-compact-padding-horizontal) +
          var(--pantoken-banner-close-button-reserve)
      );
      font-size: var(--instui-component-text-content-small-font-size);
      font-weight: var(--instui-component-text-content-small-font-weight);
      line-height: var(--instui-component-text-content-small-line-height);
    }

    /* relaxed is the default; selector exists so cssdoc can verify the modifier */
    &:is(.-size-relaxed, .-size-md) {
      --pantoken-banner-size: relaxed;
      font-size: var(--instui-component-text-content-font-size);
      font-weight: var(--instui-component-text-content-font-weight);
      line-height: var(--instui-component-text-content-line-height);
    }

    &.-color-violet {
      --pantoken-banner-icon-background: var(--instui-component-banner-violet-icon-background);
      background: var(--instui-component-banner-violet-background);
    }

    &.-color-sea {
      --pantoken-banner-icon-background: var(--instui-component-banner-sea-icon-background);
      background: var(--instui-component-banner-sea-background);
    }

    &::before {
      /* @ref 1 */
      content: "";
      position: absolute;
      inset-block-start: var(--pantoken-banner-icon-inset-block-start);
      inset-inline-start: var(--pantoken-banner-icon-inset-inline-start);
      inline-size: var(--pantoken-banner-icon-size);
      block-size: var(--pantoken-banner-icon-size);
      border-radius: var(--instui-component-banner-relaxed-icon-border-radius);
      background: var(--pantoken-banner-icon-background);
    }

    &::after {
      /* @ref 1 */
      content: "";
      position: absolute;
      inset-block-start: var(--pantoken-banner-icon-inset-block-start);
      inset-inline-start: var(--pantoken-banner-icon-inset-inline-start);
      inline-size: var(--pantoken-banner-icon-size);
      block-size: var(--pantoken-banner-icon-size);
      background: var(--instui-component-banner-icon-color);
      -webkit-mask: var(--pantoken-banner-glyph) center / 1.125rem no-repeat;
      mask: var(--pantoken-banner-glyph) center / 1.125rem no-repeat;
    }

    &:is(.-size-compact, .-size-sm)::before {
      border-radius: var(--instui-component-banner-compact-icon-border-radius);
    }

    &:is(.-size-relaxed, .-size-md)::before {
      border-radius: var(--instui-component-banner-relaxed-icon-border-radius);
    }

    /* Preserve the icon swatch when the shared `-icon-*` painter targets ::before. */
    &:is([class^="-icon-"], [class*=" -icon-"]) {
      --pantoken-banner-glyph: var(--pantoken-glyph);
    }

    &:is([class^="-icon-"], [class*=" -icon-"])::before {
      background: var(--pantoken-banner-icon-background);
      -webkit-mask: none;
      mask: none;
    }

    > :is(h1, h2, h3, h4, h5, h6, .pfx-heading:not([class*="-level-"])) {
      font-size: var(--instui-component-heading-title-card-regular-font-size);
      font-weight: var(--instui-component-heading-title-card-regular-font-weight);
      margin: 0;
    }

    &:is(.-size-compact, .-size-sm)
      > :is(h1, h2, h3, h4, h5, h6, .pfx-heading:not([class*="-level-"])) {
      font-size: var(--instui-component-heading-title-card-mini-font-size);
      font-weight: var(--instui-component-heading-title-card-mini-font-weight);
    }

    &:is(.-size-relaxed, .-size-md)
      > :is(h1, h2, h3, h4, h5, h6, .pfx-heading:not([class*="-level-"])) {
      font-size: var(--instui-component-heading-title-card-regular-font-size);
      font-weight: var(--instui-component-heading-title-card-regular-font-weight);
    }

    > .pfx-close-button:not([class*="-size-"]) {
      min-height: var(--instui-component-base-button-small-height);
    }

    > .pfx-close-button {
      position: absolute;
      inset-block-start: var(--instui-component-banner-close-button-margin-top);
      inset-inline-end: var(--instui-component-banner-close-button-margin-right);
    }

    &:has(> .pfx-close-button) {
      --pantoken-banner-close-button-reserve: calc(
        var(--instui-component-base-button-medium-height) +
          var(--instui-component-banner-close-button-margin-right)
      );
    }

    > .button-group {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: var(--instui-component-shared-tokens-spacing-gap-buttons);
    }

    /* Buttons size to their content instead of stretching full width. */
    > .pfx-button,
    > .button-group,
    > .button-group > .pfx-button {
      align-self: flex-start;
    }

    /* @ref 5 */
    > .pfx-button:not([class*="-size-"]),
    > .button-group > .pfx-button:not([class*="-size-"]) {
      font-size: var(--instui-component-base-button-small-font-size);
      min-height: var(--instui-component-base-button-small-height);
      padding-inline: var(--instui-component-base-button-small-padding-horizontal);
    }

    >.pfx-button:not([class*="-color-"]),
    /* fallow-ignore-next-line code-duplication -- standalone banner actions intentionally match the core primary-button token contract */
    >.button-group>.pfx-button:not(:has(+ .pfx-button)):not([class*="-color-"]) {
      background: var(--instui-color-background-interactive-action-primary-base);
      border-color: var(--instui-color-stroke-interactive-action-primary-base);
      color: var(--instui-color-text-interactive-action-primary-base);

      &:focus,
      /* fallow-ignore-next-line code-duplication -- standalone banner actions retain the core primary-button states */
      &:hover {
        background: var(--instui-color-background-interactive-action-primary-hover);
        border-color: var(--instui-color-stroke-interactive-action-primary-hover);
      }

      &:active {
        background: var(--instui-color-background-interactive-action-primary-active);
        border-color: var(--instui-color-stroke-interactive-action-primary-active);
      }

      &:is(:disabled, [aria-disabled="true"]) {
        background: var(--instui-component-base-button-primary-disabled-background-color);
        border-color: var(--instui-component-base-button-primary-disabled-border-color);
        color: var(--instui-component-base-button-primary-disabled-text-color);
        cursor: not-allowed;
      }
    }

    /* fallow-ignore-next-line code-duplication */
    > .button-group > .pfx-button:has(+ .pfx-button):not([class*="-color-"]) {
      background: transparent;
      border-color: var(--instui-component-base-button-primary-ghost-border-color);
      color: var(--instui-component-base-button-primary-ghost-color);

      &:focus,
      /* fallow-ignore-next-line code-duplication */
      &:hover {
        background: var(--instui-component-base-button-primary-ghost-hover-background);
        border-color: var(--instui-component-base-button-tertiary-hover-border-color);
        color: var(--instui-component-base-button-tertiary-hover-text-color);
      }

      &:active {
        background: var(--instui-component-base-button-primary-ghost-active-background);
        border-color: var(--instui-component-base-button-tertiary-active-border-color);
        color: var(--instui-component-base-button-tertiary-active-text-color);
      }

      &:is(:disabled, [aria-disabled="true"]) {
        background: transparent;
        border-color: var(--instui-component-base-button-tertiary-disabled-border-color);
        color: var(--instui-component-base-button-tertiary-disabled-text-color);
        cursor: not-allowed;
      }
    }
  }
}

