      var(--instui-component-banner-relaxed-padding-horizontal) + var(--pantoken-banner-icon-size) +
        var(--instui-component-banner-relaxed-content-gap-horizontal)
    );
    padding-inline-end: calc(
      var(--instui-component-banner-relaxed-padding-horizontal) +
        var(--pantoken-banner-close-button-reserve)
    );
    background: var(--instui-component-banner-violet-background);
    font-size: var(--instui-font-size-text-base);
    line-height: var(--instui-line-height-standalone-text-base);

    &:is(.-size-compact, .-size-sm) {
      --pantoken-banner-icon-size: 1.5rem;
      --pantoken-banner-icon-inset-block-start: var(
        --instui-component-banner-compact-padding-vertical
      );
      --pantoken-banner-icon-inset-inline-start: var(
        --instui-component-banner-compact-padding-horizontal
      );
      padding-block: var(--instui-component-banner-compact-padding-vertical);
      padding-inline-start: calc(
        var(--instui-component-banner-compact-padding-horizontal) +
          var(--pantoken-banner-icon-size) +
          var(--instui-component-banner-compact-content-gap-horizontal)
      );
      padding-inline-end: calc(
        var(--instui-component-banner-compact-padding-horizontal) +
          var(--pantoken-banner-close-button-reserve)
      );
