    &:is(.-size-relaxed, .-size-md) {
      --pantoken-banner-size: relaxed;
      font-size: var(--instui-component-text-content-font-size);
      font-weight: var(--instui-component-text-content-font-weight);
      line-height: var(--instui-component-text-content-line-height);
    }

    &.-color-violet {
      --pantoken-banner-icon-background: var(--instui-component-banner-violet-icon-background);
      background: var(--instui-component-banner-violet-background);
    }

    &.-color-sea {
      --pantoken-banner-icon-background: var(--instui-component-banner-sea-icon-background);
      background: var(--instui-component-banner-sea-background);
    }

