      /* @ref 1 */
      content: "";
      position: absolute;
      inset-block-start: var(--pantoken-banner-icon-inset-block-start);
      inset-inline-start: var(--pantoken-banner-icon-inset-inline-start);
      inline-size: var(--pantoken-banner-icon-size);
      block-size: var(--pantoken-banner-icon-size);
      border-radius: var(--instui-component-banner-relaxed-icon-border-radius);
      background: var(--pantoken-banner-icon-background);
    }

