      --pantoken-banner-close-button-reserve: calc(
        var(--instui-component-base-button-medium-height) +
          var(--instui-component-banner-close-button-margin-right)
      );
    }

    > .button-group {
      display: flex;
      align-items: center;
      flex-wrap: wrap;
      gap: var(--instui-component-shared-tokens-spacing-gap-buttons);
    }

    /* Buttons size to their content instead of stretching full width. */
    > .pfx-button,
    > .button-group,
    > .button-group > .pfx-button {
      align-self: flex-start;
    }

    /* @ref 5 */
    > .pfx-button:not([class*="-size-"]),
    > .button-group > .pfx-button:not([class*="-size-"]) {
      font-size: var(--instui-component-base-button-small-font-size);
      min-height: var(--instui-component-base-button-small-height);
      padding-inline: var(--instui-component-base-button-small-padding-horizontal);
    }

