/* Solid fills (bare, primary, danger, success) paint their border in the fill color, so tint the
   seam with the label color instead. Doubled classes outrank the group hover/active rules. */
.pfx-button-set.pfx-button-set:not(
    .-without-seam,
    .-color-secondary,
    .-color-tertiary,
    .-color-ai,
    .-color-ai-secondary,
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border
  )
  > .pfx-button:not(
    [class*="-color-"],
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border,
    [aria-pressed="true"],
    :disabled,
    [aria-disabled="true"],
    :last-child
  ),
.pfx-button-set.pfx-button-set:not(
    .-without-seam,
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border
  )
  > .pfx-button:is(.-color-primary, .-color-danger, .-color-success):not(
    .-on-color,
    .-condensed,
    .-without-background,
    .-without-border,
    [aria-pressed="true"],
    :disabled,
    [aria-disabled="true"],
    :last-child
  ) {
  border-inline-end-color: color-mix(in srgb, currentColor 35%, transparent);
}

