/**
 * @component pill
 * @selector .pfx-pill
 * @a11y The status colors are visual only, so state the status in the label text or a visually hidden label. The leading glyph is a masked `::before` and isn't announced.
 * @summary A compact status label; add a leading glyph with the shared `-icon-<name>` form.
 * @remarks Unlike `badge`, which shows a count, or `tag`, which is removable, the pill is a static status label; its leading glyph is a masked `::before`, not an `<img>`. Let groups wrap with `flex-wrap: wrap` on their container so compact labels reflow on narrow screens.
 * @modifier -size-x-small — The smallest pill size.
 * @modifier -size-medium — The medium pill size.
 * @modifier -size-large — The largest pill size.
 * @modifier -color-neutral — A neutral status.
 * @modifier -color-info — Informational status.
 * @modifier -color-success — Positive status.
 * @modifier -color-warning — Cautionary status.
 * @modifier -color-danger — Error status.
 * @modifier -color-plum — Plum accent status.
 * @modifier -color-aurora — Aurora accent status.
 * @modifier -color-sky — Sky accent status.
 * @modifier -color-orange — Orange accent status.
 * @modifier -color-violet — Violet accent status.
 * @modifier -color-sea — Sea accent status.
 * @modifier -color-stone — Stone accent status.
 * @modifier -icon-* — A leading glyph from the icon set (e.g. `-icon-check`), painted before the label.
 * @pseudo ::before — The leading icon glyph, sized and spaced to the pill.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-view --display-flex --gap-md" style="flex-wrap: wrap">
 *   <span class="instui-pill -color-success -icon-check">Published</span>
 *   <span class="instui-pill">Draft</span>
 *   <span class="instui-pill -color-info">In review</span>
 *   <span class="instui-pill -color-warning">Stale</span>
 *   <span class="instui-pill -color-danger">Blocked</span>
 *   <span class="instui-pill -color-violet">Pastel</span>
 * </div>
 * ```
 * @related badge — A badge is the count or notification counterpart.
 * @related tag — A tag is the removable, form-oriented counterpart.
 * @example -automatica11y
 * ```html
 * <div class="pfx-view --display-flex --gap-md" style="flex-wrap: wrap">
 *   <span class="pfx-pill -color-success -icon-check">Published</span>
 *   <span class="pfx-pill">Draft</span>
 *   <span class="pfx-pill -color-info">In review</span>
 *   <span class="pfx-pill -color-warning">Stale</span>
 *   <span class="pfx-pill -color-danger">Blocked</span>
 *   <span class="pfx-pill -color-violet">Pastel</span>
 * </div>
 * ```
 */
@scope (.pfx-pill) {
  & {
    display: inline-flex;
    align-items: center;
    height: var(--instui-component-pill-height);
    max-width: var(--instui-component-pill-max-width);
    padding-block: var(--instui-component-pill-padding-vertical);
    padding-inline: var(--instui-component-pill-padding-horizontal);
    gap: var(--instui-component-pill-gap-content);
    background: var(--instui-component-pill-neutral-background-color);
    color: var(--instui-component-pill-base-text-color);
    border: var(--instui-component-pill-border-width) var(--instui-component-pill-border-style)
      var(--instui-component-pill-base-border-color);
    border-radius: var(--instui-component-pill-border-radius);
    font-family: var(--instui-component-pill-font-family);
    font-size: var(--instui-component-pill-text-font-size);
    font-weight: var(--instui-component-pill-text-font-weight);
    line-height: var(--instui-component-pill-line-height);
  }

  &:is([class^="-icon-"], [class*=" -icon-"])::before {
    inline-size: var(--instui-font-size-text-xs);
    block-size: var(--instui-font-size-text-xs);
    margin-inline-end: var(--instui-component-pill-gap-icon-label);
  }

  &.-size-x-small {
    height: var(--instui-component-pill-height-x-small);
  }

  &.-size-medium {
    height: var(--instui-component-pill-height-medium);
    padding-inline: var(--instui-component-pill-padding-horizontal-medium);
    font-size: var(--instui-component-pill-text-font-size-medium);
    gap: var(--instui-component-pill-gap-content);
  }

  &.-size-large {
    height: var(--instui-component-pill-height-large);
    padding-inline: var(--instui-component-pill-padding-horizontal-large);
    font-size: var(--instui-component-pill-text-font-size-large);
    gap: var(--instui-component-pill-gap-content);
  }

  &.-size-medium:is([class^="-icon-"], [class*=" -icon-"])::before {
    margin-inline-end: var(--instui-component-pill-gap-icon-label-medium);
  }

  &.-size-large:is([class^="-icon-"], [class*=" -icon-"])::before {
    margin-inline-end: var(--instui-component-pill-gap-icon-label-large);
  }

  &.-color-neutral {
    background: var(--instui-component-pill-neutral-background-color);
  }

  &.-color-info {
    background: var(--instui-component-pill-info-background-color);
    color: var(--instui-component-pill-info-text-color);
    border-color: var(--instui-component-pill-info-border-color);
  }

  &.-color-success {
    background: var(--instui-component-pill-success-background-color);
    color: var(--instui-component-pill-success-text-color);
    border-color: var(--instui-component-pill-success-border-color);
  }

  &.-color-warning {
    background: var(--instui-component-pill-warning-background-color);
    color: var(--instui-component-pill-warning-text-color);
    border-color: var(--instui-component-pill-warning-border-color);
  }

  &:is(.-color-danger, .-color-error) {
    background: var(--instui-component-pill-error-background-color);
    color: var(--instui-component-pill-error-text-color);
    border-color: var(--instui-component-pill-error-border-color);
  }

  &.-color-plum {
    background: var(--instui-component-pill-plum-background-color);
    color: var(--instui-component-pill-plum-text-color);
    border-color: var(--instui-component-pill-plum-border-color);
  }

  &.-color-aurora {
    background: var(--instui-component-pill-aurora-background-color);
    color: var(--instui-component-pill-aurora-text-color);
    border-color: var(--instui-component-pill-aurora-border-color);
  }

  &.-color-sky {
    background: var(--instui-component-pill-sky-background-color);
    color: var(--instui-component-pill-sky-text-color);
    border-color: var(--instui-component-pill-sky-border-color);
  }

