/**
 * @utility screen-reader-content
 * @summary Visually hides content while keeping it available to assistive tech (the standard clip pattern).
 * @selector .pfx-screen-reader-content
 * @a11y Keeps text in the accessibility tree for screen readers while removing it from the visual layout.
 * @example
 * ```html
 * <a class="instui-link" href="#examples" target="_blank">example</a>
 * <span class="instui-screen-reader-content">Opens in a new window</span>
 * ```
 * @example -automatica11y
 * ```html
 * <a class="pfx-link" href="#settings" data-a11y-root data-a11y-trigger>
 *   <span class="pfx-icon -icon-settings" aria-hidden="true"></span>
 *   <span class="pfx-screen-reader-content">Open settings</span>
 * </a>
 * ```
 */
@scope (.pfx-screen-reader-content) {
  & {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }
}

