/**
 * @component form-field-group
 * @selector .pfx-form-field-group
 * @summary A `<fieldset>` group with a legend, a column or inline layout, and configurable spacing.
 * @remarks Sets its own `gap` between fields, tunable with the `-col-spacing-*`/`-row-spacing-*` modifiers below — prefer those over chaining a generic `-gap-*` spacing utility modifier, which overrides the built-in value outright.
 * @modifier -col-spacing-none — No column gap.
 * @modifier -col-spacing-small — Small column gap.
 * @modifier -col-spacing-medium — Medium column gap.
 * @modifier -col-spacing-large — Large column gap.
 * @modifier -row-spacing-none — No row gap.
 * @modifier -row-spacing-small — Small row gap.
 * @modifier -row-spacing-medium — Medium row gap.
 * @modifier -row-spacing-large — Large row gap.
 * @modifier -layout-aligned — Align child fields to a shared grid.
 * @modifier -layout-columns — Lay child fields out in columns.
 * @modifier -layout-inline — Lay child fields inline, in a row.
 * @modifier -required — Mark the group as required.
 * @modifier -v-align-top — Top-align the fields.
 * @modifier -v-align-middle — Middle-align the fields.
 * @modifier -v-align-bottom — Bottom-align the fields.
 * @pseudo ::after — Renders the decorative required-field asterisk after the legend text when the group is required.
 * @accessibility Renders a native `<fieldset>` with a `<legend>`, so the legend text names the whole group for assistive tech.
 * @compat The `-layout-aligned` mode uses CSS subgrid behind an `@supports` guard; where subgrid is unsupported, the fields fall back to their own stacked layout.
 * @example -canvas-rce -docs
 * ```html
 * <fieldset class="pfx-form-field-group -layout-columns -col-spacing-medium">
 *   <legend>Shipping address</legend>
 *   <label class="pfx-form-field">
 *     <span class="label">First name</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">Last name</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">City</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">State</span>
 *     <span class="controls">
 *       <select class="pfx-simple-select">
 *         <option>CA</option>
 *         <option>NY</option>
 *         <option>TX</option>
 *       </select>
 *     </span>
 *   </label>
 *   <div class="pfx-form-field-messages">
 *     <span class="pfx-form-field-message -type-hint">All fields are used for delivery only.</span>
 *   </div>
 * </fieldset>
 * ```
 * @structure
 * .pfx-form-field-group.-layout-columns.-col-spacing-medium {
 *   legend {}
 *   .pfx-form-field {}
 *   .pfx-form-field-messages {}
 * }
 * @related form-field — The single field this group repeats.
 * @related radio-input-group — Groups radio inputs under a legend.
 * @example -automatica11y
 * ```html
 * <fieldset class="pfx-form-field-group -layout-columns -col-spacing-medium">
 *   <legend>Shipping address</legend>
 *   <label class="pfx-form-field">
 *     <span class="label">First name</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">Last name</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">City</span>
 *     <span class="controls"><input class="pfx-text-input"></span>
 *   </label>
 *   <label class="pfx-form-field">
 *     <span class="label">State</span>
 *     <span class="controls">
 *       <select class="pfx-simple-select">
 *         <option>CA</option>
 *         <option>NY</option>
 *         <option>TX</option>
 *       </select>
 *     </span>
 *   </label>
 *   <div class="pfx-form-field-messages">
 *     <span class="pfx-form-field-message -type-hint">All fields are used for delivery only.</span>
 *   </div>
 * </fieldset>
 * ```
 */
@scope (.pfx-form-field-group) {
  & {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--instui-component-form-field-layout-gap-inputs);
    min-inline-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

  & > legend {
    grid-column: 1 / -1;
    padding: 0;
    margin-block-end: var(--instui-component-form-field-layout-gap-primitives);
    color: var(--instui-component-form-field-layout-text-color);
    font-family: var(--instui-component-form-field-layout-font-family);
    font-weight: var(--instui-component-form-field-layout-font-weight);
    font-size: var(--instui-component-form-field-layout-font-size);
    line-height: var(--instui-component-form-field-layout-line-height);
  }

  &.-required > legend::after {
    content: "*";
    margin-inline-start: 0.25rem;
    color: var(--instui-component-form-field-layout-asterisk-color);
  }

  &.-layout-columns,
  &.-layout-inline {
    grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  }

  &.-row-spacing-none {
