/**
 * @component heading
 * @summary Heading typography from `-level-h1` to `-level-h6`.
 * @remarks The `-variant-*` presets override a `-level-*`'s font-size and font-weight, so combine only one of each family per element.
 * @selector .pfx-heading
 * @modifier -level-h1 — Render at the h1 type scale.
 * @modifier -level-h2 — Render at the h2 type scale.
 * @modifier -level-h3 — Render at the h3 type scale.
 * @modifier -level-h4 — Render at the h4 type scale.
 * @modifier -level-h5 — Render at the h5 type scale.
 * @modifier -level-h6 — Render at the h6 type scale.
 * @modifier -color-primary — (default) Primary colour.
 * @modifier -color-secondary — Secondary (muted) colour.
 * @modifier -color-ai — AI-accent colour.
 * @modifier -color-primary-inverse — On-dark (primary inverse) colour.
 * @modifier -border-top — Add a top rule.
 * @modifier -border-bottom — Add a bottom rule.
 * @modifier -variant-label — Label type preset.
 * @modifier -variant-title-page — Page-title preset.
 * @modifier -variant-title-section — Section-title preset.
 * @modifier -variant-title-card-mini — Mini card-title preset.
 * @modifier -variant-title-card-regular — Regular card-title preset.
 * @modifier -variant-title-card-section — Card section-title preset.
 * @accessibility These classes set the visual level only, so render a real `<h1>`–`<h6>` (or use `role="heading"` with `aria-level`) to convey the heading level.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-heading -level-h1">Heading h1</div>
 * ```
 * @related text — Body typography for non-heading text.
 * @example -automatica11y
 * ```html
 * <h2 class="pfx-heading -level-h2">Account details</h2>
 * ```
 */
@scope (.pfx-heading) {
  & {
    display: block;
    margin: 0;
    font-family: var(--instui-component-heading-h1-font-family);
    color: var(--instui-component-heading-base-color);
    line-height: var(--instui-component-heading-line-height);
    font-size: var(--instui-component-heading-h1-font-size);
    font-weight: var(--instui-component-heading-h1-font-weight);
  }

  &.-level-h1 {
    font-size: var(--instui-component-heading-h1-font-size);
    font-weight: var(--instui-component-heading-h1-font-weight);
  }

  &.-level-h2 {
    font-size: var(--instui-component-heading-h2-font-size);
    font-weight: var(--instui-component-heading-h2-font-weight);
  }

  &.-level-h3 {
    font-size: var(--instui-component-heading-h3-font-size);
    font-weight: var(--instui-component-heading-h3-font-weight);
  }

  &.-level-h4 {
    font-size: var(--instui-component-heading-h4-font-size);
    font-weight: var(--instui-component-heading-h4-font-weight);
  }

  &.-level-h5 {
    font-size: var(--instui-component-heading-h5-font-size);
    font-weight: var(--instui-component-heading-h5-font-weight);
  }

  &.-level-h6 {
    font-size: var(--instui-component-heading-h6-font-size);
    font-weight: var(--instui-component-heading-h6-font-weight);
  }

  &.-variant-title-page {
    font-size: var(--instui-component-heading-title-page-desktop-font-size);
    font-weight: var(--instui-component-heading-title-page-desktop-font-weight);
  }

  &.-variant-title-section {
    font-size: var(--instui-component-heading-title-section-font-size);
    font-weight: var(--instui-component-heading-title-section-font-weight);
  }

  &.-variant-title-card-section {
    font-size: var(--instui-component-heading-title-card-section-font-size);
    font-weight: var(--instui-component-heading-title-card-section-font-weight);
  }

  &.-variant-title-card-regular {
    font-size: var(--instui-component-heading-title-card-regular-font-size);
    font-weight: var(--instui-component-heading-title-card-regular-font-weight);
  }

  &.-variant-title-card-mini {
    font-size: var(--instui-component-heading-title-card-mini-font-size);
    font-weight: var(--instui-component-heading-title-card-mini-font-weight);
  }

  &.-variant-label {
    font-size: var(--instui-component-heading-label-font-size);
    font-weight: var(--instui-component-heading-label-font-weight);
  }

  &.-color-primary {
    color: var(--instui-component-heading-base-color);
  }

  &.-color-secondary {
    color: var(--instui-component-heading-muted-color);
  }

  &.-color-primary-inverse {
    color: var(--instui-component-heading-inverse-color);
  }

  &.-color-ai {
    background: linear-gradient(
      to bottom,
      var(--instui-component-heading-ai-text-top-gradient-color) 0%,
      var(--instui-component-heading-ai-text-bottom-gradient-color) 100%
    );
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
    @media (forced-colors: active) {
      background: none;
      color: CanvasText;
      -webkit-text-fill-color: currentColor;
    }
  }

  &.-border-bottom {
    border-bottom: var(--instui-component-heading-border-width) solid
      var(--instui-component-heading-border-color);
    padding-bottom: var(--instui-component-heading-border-padding);
  }

  &.-border-top {
    border-top: var(--instui-component-heading-border-width) solid
      var(--instui-component-heading-border-color);
    padding-top: var(--instui-component-heading-border-padding);
  }

