/**
 * @component close-button
 * @selector .pfx-close-button
 * @summary A transparent icon button that draws its own × glyph, in three sizes plus an on-color variant.
 * @remarks Always renders as an icon-only control with no visible label, so an `aria-label` is required, not optional; compare to `button`'s `-without-background` ghost variant, which keeps a text label.
 * @modifier -color-inverse — @deprecated {@link -on-color}
 * @modifier -on-color — For a close button placed on a coloured (non-neutral) surface.
 * @modifier -size-sm — Small.
 * @modifier -size-md — (default) medium size.
 * @modifier -size-lg — Large.
 * @cssstate disabled
 * @pseudo ::before — The × glyph, masked in `currentColor`.
 * @a11y Give the icon-only button an `aria-label` (e.g. "Close"), and mark a disabled button with `aria-disabled` (or the native `disabled`).
 * @example -canvas-rce -docs
 * ```html
 * <button class="pfx-close-button -size-sm" aria-label="Close"></button>
 * ```
 * @related button — The general-purpose action button.
 * @example -automatica11y
 * ```html
 * <button class="pfx-close-button -size-sm" aria-label="Close"></button>
 * ```
 */
@scope (.pfx-close-button) {
  & {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    aspect-ratio: 1;
    min-height: var(--instui-component-base-button-medium-height);
    padding: var(--instui-spacing-space-xs);
    border: 0;
    background: transparent;
    border-radius: var(--instui-component-base-button-border-radius);
    color: var(--instui-component-icon-base-color);
    cursor: pointer;
  }

  &::before {
    content: "";
    inline-size: 1em;
    block-size: 1em;
    background: currentColor;
    -webkit-mask: var(--instui-icon-x) center / contain no-repeat;
    mask: var(--instui-icon-x) center / contain no-repeat;
    @media (forced-colors: active) {
      forced-color-adjust: preserve-parent-color;
      background: currentColor;
    }
  }

  &:hover {
    background: var(--instui-component-base-button-primary-ghost-hover-background);
  }

  &:active {
    background: var(--instui-component-base-button-primary-ghost-active-background);
  }

  &:disabled,
  &[aria-disabled="true"] {
    color: var(--instui-component-icon-disabled-base-color);
    cursor: not-allowed;
  }

  &.-size-sm {
    min-height: var(--instui-component-base-button-small-height);
  }

  &.-size-md {
    min-height: var(--instui-component-base-button-medium-height);
  }

  &.-size-lg {
    min-height: var(--instui-component-base-button-large-height);
  }

  &.-on-color,
  &.-color-inverse {
    color: var(--instui-component-icon-on-color);
  }

  &.-on-color:hover,
  &.-color-inverse:hover {
    background: var(--instui-component-base-button-primary-inverse-ghost-hover-background);
  }

  &.-on-color:active,
  &.-color-inverse:active {
    background: var(--instui-component-base-button-primary-inverse-ghost-active-background);
  }

  &.-on-color:disabled,
  &.-on-color[aria-disabled="true"],
  &.-color-inverse:disabled,
  &.-color-inverse[aria-disabled="true"] {
    color: var(--instui-component-icon-disabled-on-color);
  }
}

