/**
 * @component file-drop
 * @selector .pfx-file-drop
 * @summary A file dropzone with hover, accepted, and rejected states.
 * @remarks The `-hover`/`-accepted`/`-rejected` classes are purely visual — actual drag-and-drop detection and file validation are the consumer's JS to wire up around the wrapped native input.
 * @modifier -icon-* — Render the leading dropzone glyph icon.
 * @modifier -accepted — Drag state for an acceptable file.
 * @modifier -hover — Hover or drag-over state.
 * @modifier -rejected — Drag state for a rejected file.
 * @accessibility Wrap a native `<input type="file">` in the `<label>` drop zone so it stays a real, labelled file control that the keyboard and assistive tech can operate.
 * @example -canvas-rce -docs
 * ```html
 * <label class="pfx-file-drop" id="fd">
 *   <span class="pfx-icon -icon-cloud-upload"></span>
 *   <div class="pfx-text"><strong>Drag an image here</strong>, or click to browse.</div>
 *   <div class="pfx-text -size-sm pfx-fg-muted" id="fd-msg">PNG or JPG up to 5&nbsp;MB.</div>
 *   <input type="file" id="fd-input">
 * </label>
 * ```
 * @structure
 * .pfx-file-drop {
 *   [class*="-icon-"]:optional {}
 *   .pfx-text {
 *     strong {}
 *   }
 *   .pfx-text {}
 *   input {}
 * }
 * @example -automatica11y
 * ```html
 * <label class="pfx-file-drop" id="fd">
 *   <span class="pfx-icon -icon-cloud-upload"></span>
 *   <div class="pfx-text"><strong>Drag an image here</strong>, or click to browse.</div>
 *   <div class="pfx-text -size-sm pfx-fg-muted" id="fd-msg">PNG or JPG up to 5&nbsp;MB.</div>
 *   <input type="file" id="fd-input">
 * </label>
 * ```
 */
@scope (.pfx-file-drop) {
  & {
    display: block;
    text-align: center;
    padding: var(--instui-spacing-space-lg);
    color: var(--instui-color-text-base);
    background: var(--instui-component-file-drop-background-color);
    border: var(--instui-component-file-drop-border-width)
      var(--instui-component-file-drop-border-style) var(--instui-component-file-drop-border-color);
    border-radius: var(--instui-component-file-drop-border-radius);
  }

  &:hover,
  &.-hover {
    border-color: var(--instui-component-file-drop-hover-border-color);
  }

  &.-accepted {
    border-color: var(--instui-component-file-drop-accepted-color);
  }

  &.-rejected {
    border-color: var(--instui-component-file-drop-rejected-color);
  }

  & > :is([class^="-icon-"], [class*=" -icon-"]) {
    line-height: 1;
  }
}

