/**
 * @component spinner
 * @selector .pfx-spinner
 * @summary An animated loading ring or AI spinner; give it role="status" and an aria-label.
 * @remarks `-color-inverse` only repaints the animated top border segment, not the whole track, so it still reads correctly on a dark card without needing a separate track color. The AI variants replace the ring with the centred `ai-spinner` glyph while keeping the same size scale.
 * @modifier -size-xs — Extra-small.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @modifier -color-inverse — On a dark surface.
 * @modifier -color-ai — Rotating AI-gradient star.
 * @modifier -color-ai-on-color — Rotating on-colour AI star for a coloured or dark surface.
 * @animation pantoken-spinner-rotate — Rotates the ring, or the AI star at the slower 2.25-second cadence.
 * @a11y Give the spinner role="status" and an aria-label so screen readers announce it as a live loading status.
 * @a11y With reduced motion enabled, the ring or AI glyph remains visible without rotation; keep the loading status and label while work is pending.
 * @example -canvas-rce -docs
 * ```html
 * <span class="pfx-spinner" role="status" aria-label="Loading"></span>
 * ```
 * ### Inverse color -nocard
 * ```html
 * <div class="instui-view instui-card -background-primary-inverse">
 *   <span class="pfx-spinner -color-inverse" role="status" aria-label="Loading"></span>
 * </div>
 * ```
 * @demo self:spinner
 * @example -automatica11y
 * ```html
 * <span class="pfx-spinner" role="status" aria-label="Loading"></span>
 * 
 * <div class="pfx-view pfx-card -background-primary-inverse">
 *   <span class="pfx-spinner -color-inverse" role="status" aria-label="Loading"></span>
 * </div>
 * ```
 */
@keyframes pantoken-spinner-rotate {
  to {
    transform: rotate(360deg);
  }
}

@scope (.pfx-spinner) {
  :scope {
    display: inline-block;
    width: var(--instui-component-spinner-spinner-size-md);
    height: var(--instui-component-spinner-spinner-size-md);
    border: var(--instui-component-spinner-stroke-width-md) solid
      var(--instui-component-spinner-track-color);
    border-top-color: var(--instui-component-spinner-color);
    border-radius: 50%;
    animation: pantoken-spinner-rotate 0.8s linear infinite;

    &.-color-inverse {
      border-top-color: var(--instui-component-spinner-inverse-color);
    }

    &.-color-ai,
    &.-color-ai-on-color {
      border: 0;
      border-radius: 0;
      animation-duration: 2.25s;
      -webkit-mask: var(--instui-icon-ai-spinner) center / contain no-repeat;
      mask: var(--instui-icon-ai-spinner) center / contain no-repeat;
    }

    &.-color-ai {
      background: linear-gradient(
        to bottom,
        var(--instui-color-stroke-ai-top-gradient),
        var(--instui-color-stroke-ai-bottom-gradient)
      );
    }

    &.-color-ai-on-color {
      background: var(--instui-color-icon-on-color);
    }

    @media (forced-colors: active) {
      &.-color-ai,
      &.-color-ai-on-color {
        forced-color-adjust: preserve-parent-color;
        background: currentColor;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }
}

.pfx-spinner.-size-xs {
  width: var(--instui-component-spinner-spinner-size-xs);
  height: var(--instui-component-spinner-spinner-size-xs);
  border-width: var(--instui-component-spinner-stroke-width-xs);
}

.pfx-spinner.-size-sm {
  width: var(--instui-component-spinner-spinner-size-sm);
  height: var(--instui-component-spinner-spinner-size-sm);
  border-width: var(--instui-component-spinner-stroke-width-sm);
}

.pfx-spinner.-size-lg {
  width: var(--instui-component-spinner-spinner-size-lg);
  height: var(--instui-component-spinner-spinner-size-lg);
  border-width: var(--instui-component-spinner-stroke-width-lg);
}

