/**
 * @component context-view
 * @selector .pfx-context-view
 * @a11y Connect the trigger with `popovertarget` so the open state is exposed, and keep the native Escape and outside-click dismissal. The caret is decorative; the callout's content isn't announced unless the trigger references it, for example with `aria-describedby`.
 * @summary An elevated callout with a caret, positionable on any side; works as a native `[popover]`.
 * @remarks The caret is two stacked `::before`/`::after` triangles (border then fill) so it reads correctly against a matching surface; as a `[popover]` it needs the same open/`popovertarget` wiring as `popover`, but unlike `tooltip`, it dismisses on outside click or Escape.
 * @modifier -color-inverse — Dark (inverse) colour scheme.
 * @modifier -placement-top — Sit above the anchor.
 * @modifier -placement-bottom — Sit below the anchor.
 * @modifier -placement-start — Sit at the start (inline-start) of the anchor.
 * @modifier -placement-end — Sit at the end (inline-end) of the anchor.
 * @pseudo ::before — Renders the caret's outer border triangle.
 * @pseudo ::after — Renders the caret's inner fill triangle.
 * @cssstate open
 * @compat Uses CSS anchor positioning (`position-anchor`, `position-area`, `position-try-fallbacks`) and the native `[popover]` API behind an `@supports` guard; needs a recent Chromium or Safari, and falls back to a UA-centred popover elsewhere.
 * @example -canvas-rce -docs
 * ```html
 * <div class="pfx-context-view -placement-bottom" id="cv-popover">A context view frames a callout with a caret. As a popover it rides the top layer and closes when you click away or press Esc.</div>
 * ```
 * @related popover — The generic top-layer popover.
 * @related tooltip — A smaller hover or focus callout.
 * @example -automatica11y
 * ```html
 * <div class="pfx-context-view -placement-bottom" id="cv-popover">A context view frames a callout with a caret. As a popover it rides the top layer and closes when you click away or press Esc.</div>
 * ```
 */
@scope (.pfx-context-view) {
  & {
    position: relative;
    display: inline-block;
    padding: var(--instui-spacing-space-md);
    background: var(--instui-color-background-elevated-surface-base);
    color: var(--instui-color-text-base);
    border: var(--instui-component-context-view-arrow-border-width) solid
      var(--instui-component-context-view-arrow-border-color);
    border-radius: var(--instui-component-context-view-border-radius);
    /* ContextView floats over content — InstUI gives it a shadow. */
    box-shadow: var(--instui-elevation-above);
  }

  /* The caret is two stacked triangles: ::before is the border (outer, one border-width larger) and
     ::after is the fill (inner). Both are anchored to the same edge so the border peeks around the fill —
     without it, a surface-coloured caret is invisible against a matching surface. */
  &::before,
  &::after {
    content: "";
    position: absolute;
    border-style: solid;
    border-color: transparent;
  }

  /* Default placement="top": the view sits above its target, so the caret is on the bottom edge
     pointing down. */
  &::before {
    top: 100%;
    inset-inline-start: calc(
      var(--instui-spacing-space-lg) - var(--instui-component-context-view-arrow-border-width)
    );
    border-top-color: var(--instui-component-context-view-arrow-border-color);
    border-width: calc(
      var(--instui-component-context-view-arrow-size) +
        var(--instui-component-context-view-arrow-border-width)
    );
  }

  &::after {
    top: 100%;
    inset-inline-start: var(--instui-spacing-space-lg);
    border-width: var(--instui-component-context-view-arrow-size);
    border-top-color: var(--instui-component-context-view-arrow-background-color);
  }

  /* placement="bottom": caret on the top edge, pointing up. */
  &.-placement-bottom::before {
    top: auto;
    bottom: 100%;
    border-top-color: transparent;
    border-bottom-color: var(--instui-component-context-view-arrow-border-color);
  }

  &.-placement-bottom::after {
    top: auto;
    bottom: 100%;
    border-top-color: transparent;
    border-bottom-color: var(--instui-component-context-view-arrow-background-color);
  }

  /* placement="start": the view sits before its target, caret on the inline-end edge pointing toward it. */
  &.-placement-start::before,
  &.-placement-start::after {
    top: 50%;
    inset-inline-start: 100%;
    transform: translateY(-50%);
    border-top-color: transparent;
  }

  &.-placement-start::before {
    border-inline-start-color: var(--instui-component-context-view-arrow-border-color);
  }

  &.-placement-start::after {
    border-inline-start-color: var(--instui-component-context-view-arrow-background-color);
  }

  /* placement="end": the view sits after its target, caret on the inline-start edge pointing toward it. */
  &.-placement-end::before,
  &.-placement-end::after {
    top: 50%;
    inset-inline-start: auto;
    inset-inline-end: 100%;
    transform: translateY(-50%);
    border-top-color: transparent;
  }

  &.-placement-end::before {
    border-inline-end-color: var(--instui-component-context-view-arrow-border-color);
  }

  &.-placement-end::after {
    border-inline-end-color: var(--instui-component-context-view-arrow-background-color);
  }

  /* background="inverse": dark surface, inverse text, and inverse-coloured caret layers per placement. */
  &.-color-inverse {
    background: var(--instui-color-background-inverse);
    color: var(--instui-color-text-inverse);
    border-color: var(--instui-component-context-view-arrow-border-color-inverse);
  }

  &.-color-inverse::before {
    border-top-color: var(--instui-component-context-view-arrow-border-color-inverse);
  }

  &.-color-inverse::after {
    border-top-color: var(--instui-component-context-view-arrow-background-color-inverse);
  }

  &.-color-inverse.-placement-bottom::before {
    border-top-color: transparent;
    border-bottom-color: var(--instui-component-context-view-arrow-border-color-inverse);
  }

  &.-color-inverse.-placement-bottom::after {
    border-top-color: transparent;
    border-bottom-color: var(--instui-component-context-view-arrow-background-color-inverse);
  }

  &.-color-inverse.-placement-start::before {
    border-top-color: transparent;
    border-inline-start-color: var(--instui-component-context-view-arrow-border-color-inverse);

