/**
 * @component in-place-edit
 * @selector .pfx-in-place-edit
 * @summary A [contenteditable] that reads as text until focused, then shows input chrome.
 * @remarks The input chrome only appears while focused; `-readonly` suppresses both the hover and focus affordances so the element always reads as plain inline text.
 * @modifier -readonly — Shown inline but not editable (no hover/focus affordance).
 * @a11y Give the editable element `role="textbox"` and an accessible name (`aria-label`).
 * @example -canvas-rce -docs
 * ```html
 * <span class="pfx-in-place-edit" contenteditable="true" role="textbox" aria-label="Project name">Untitled</span>
 * ```
 * @related text-input — On focus it shows the same input chrome as a text input.
 * @demo self:in-place-edit
 * @example -automatica11y
 * ```html
 * <span class="pfx-in-place-edit" contenteditable="true" role="textbox" aria-label="Project name">Untitled</span>
 * ```
 */
@scope (.pfx-in-place-edit) {
  & {
    display: inline-block;
    min-inline-size: 2rem;
    padding: var(--instui-spacing-space2xs) var(--instui-spacing-space-xs);
    border: var(--instui-component-text-input-border-width) solid transparent;
    border-radius: var(--instui-component-text-input-border-radius);
    color: var(--instui-color-text-base);
    font: inherit;
    cursor: text;
  }

  /* Hover affordance: it's editable. */
  &:hover {
    background: var(--instui-color-background-muted);
  }

  /* Focus = edit mode: input chrome + the focus ring. */
  &:focus {
    background: var(--instui-component-text-input-background-color);
    border-color: var(--instui-component-text-input-border-color);
    outline: none;
  }

  &:focus-visible {
    outline: var(--instui-focus-outline-width) var(--instui-focus-outline-style)
      var(--instui-focus-outline-color);
    outline-offset: var(--instui-focus-outline-offset);
  }

  &.-readonly {
    cursor: default;
  }

  &.-readonly:hover {
    background: transparent;
  }
}

