  css: (p) => checkboxRaw.replaceAll(SENTINEL, p),
});
/** Standalone `checkbox` stylesheet — the prefixed CSS for the checkbox and switch, ready to ship as a `.css` file. */
export const checkboxCss: Definition["css"] = checkbox.css;

