    ["primary", "base"],
    ["brand", "brand"],
    ["success", "success"],
    ["info", "info"],
    ["warning", "warning"],
    ["danger", "error"],
  ].map(([name, token]) =>
    rule(`border-color-${name}`, `border-color: var(--instui-color-stroke-${token});`),
  );

