export const view: Definition = defineComponent({
  name: "view",
  css: (p) => {
    const rule = (mod: string, decls: string): string => `&.-${mod} { ${decls} }`;
    const rules: string[] = [
      ...buildBackgroundRules(rule),
      ...buildBorderRules(rule),
