/* InstUI's withBorder={false}: drop the border but keep the button's box (border-box sizing). */
  &.-without-border {
    border-style: none;
  }

  &.-color-ai-secondary.-without-border::after {
    display: none;
  }

  @media (forced-colors: active) {
    &.-color-ai-secondary {
      &,
      &:is(:hover, :active, :disabled, [aria-disabled="true"]) {
        background: none;
        color: ButtonText;
        -webkit-text-fill-color: currentColor;
      }

      &:is(:disabled, [aria-disabled="true"]) {
        color: GrayText;
      }
    }

    &:is(.-color-ai, .-color-ai-secondary) {
      &::before,
      &:is(:disabled, [aria-disabled="true"])::before,
      &:is([class^="-icon-"], [class*=" -icon-"])::before {
        forced-color-adjust: preserve-parent-color;
        background: currentColor;
      }
    }

    &.-color-ai-secondary::after,
    &:is([class^="-icon-"], [class*=" -icon-"])::before {
      forced-color-adjust: preserve-parent-color;
  }

  /* Color modifiers paired with deprecated meter-color aliases via :is(). */
  &:is(.-color-brand, .-meter-color-brand) {
    --pantoken-progress-fill: var(--instui-color-background-brand);
  }

  &:is(.-color-info, .-meter-color-info) {
    --pantoken-progress-fill: var(--instui-color-background-info);
  }

  &:is(.-color-success, .-meter-color-success) {
    --pantoken-progress-fill: var(--instui-color-background-success);
  }

  &:is(.-color-warning, .-meter-color-warning, .-meter-color-alert) {
    --pantoken-progress-fill: var(--instui-color-background-warning);
  }

  &:is(.-color-danger, .-meter-color-danger) {
    --pantoken-progress-fill: var(--instui-color-background-error);
  }

  /* color="primary-inverse": the on-dark scheme. It's a distinct axis from meterColor and overrides it —
     InstUI's inverse meter tokens all collapse to background-base — so it comes AFTER the meter rules and
     wins at equal specificity. Pair it with a dark surface. */
  &.-color-primary-inverse {
    --pantoken-progress-fill: var(--instui-component-progress-bar-meter-color-brand-inverse);
    background: var(--instui-component-progress-bar-track-color-inverse);
    border-color: var(--instui-component-progress-bar-border-color-inverse);
    color: var(--instui-component-progress-bar-text-color-inverse);
  }

  &.-color-primary-inverse::after {
    background: var(--instui-component-progress-bar-track-bottom-border-color-inverse);
  }

  &.-render-value-inside > .value {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: flex-start;
  }

  /* Mount/value transition — the interactions layer toggles `-should-animate` on value changes. */
  &.-should-animate > .bar {
    @media (prefers-reduced-motion: no-preference) {
      transition: all 0.5s;
    }
  }
}
