      }

      /* translateX is physical while the inset is logical, so RTL needs the opposite sign to stay centered. */
      &:dir(rtl) {
        transform: translateX(50%);
      }

      /* Placement (authored on the .tip itself, matching the web-component): default is top; these move the
         bubble to the other sides. */
      &.-placement-bottom {
        inset-block: 100% auto;
        margin-block: var(--instui-spacing-space-xs) 0;

        &::before {
          inset-block: auto 100%;
        }
      }

      &.-placement-start {
        inset-block-end: auto;
        inset-inline: auto 100%;
        top: 50%;
        transform: translateY(-50%);
        margin: 0;
        margin-inline-end: var(--instui-spacing-space-xs);

        &::before {
          inset-block: 0;
          inset-inline: 100% auto;
          inline-size: var(--instui-spacing-space-xs);
          block-size: auto;
        }
      }

      &.-placement-end {
        inset-block-end: auto;
        inset-inline: 100% auto;
        top: 50%;
        transform: translateY(-50%);
        margin: 0;
        margin-inline-start: var(--instui-spacing-space-xs);

        &::before {
          inset-block: 0;
          inset-inline: auto 100%;
          inline-size: var(--instui-spacing-space-xs);
          block-size: auto;
        }
      }
    }

    > .tip[data-tooltip-side="top"]::before {
      inset: 100% 0 auto;
      width: auto;
      height: var(--pantoken-tooltip-gap, var(--instui-spacing-space-xs));
    }

    > .tip[data-tooltip-side="bottom"]::before {
      inset: auto 0 100%;
      width: auto;
      height: var(--pantoken-tooltip-gap, var(--instui-spacing-space-xs));
    }

    > .tip[data-tooltip-side="left"]::before {
      inset: 0 auto 0 100%;
      width: var(--pantoken-tooltip-gap, var(--instui-spacing-space-xs));
      height: auto;
    }

    > .tip[data-tooltip-side="right"]::before {
      inset: 0 100% 0 auto;
      width: var(--pantoken-tooltip-gap, var(--instui-spacing-space-xs));
      height: auto;
    }

    &:not([data-tooltip-managed]):hover > .tip,
    &:not([data-tooltip-managed]):focus-within > .tip,
    &[data-tooltip-managed] > .tip.-show {
      opacity: 1;
      visibility: visible;
    }
  }
}

