/**
 * @component pagination
 * @summary Page navigation: numbered pages, first, previous, next, and last arrows, and an ellipsis for gaps.
 * @remarks Sets its own `gap` between page controls; chaining a `-gap-*` spacing utility modifier overrides that built-in value.
 * @modifier -variant-input — Compact variant with a page-number input.
 * @modifier -icon-* — Render arrow glyph icons inside the first/prev/next/last controls.
 * @remarks See the `pagination.page` member for the individual page controls.
 * @part .arrow — A first, previous, next, or last control.
 * @part .ellipsis — The gap marker between page ranges.
 * @part .page-input-label — The label for the page-number input (input variant).
 * @cssstate disabled
 * @a11y Label the `<nav>` with aria-label, mark the current page with aria-current="page", give each arrow an aria-label, and disable end arrows with disabled or aria-disabled="true".
 * @example -canvas-rce -docs
 * ```html
 * <nav class="pfx-pagination" aria-label="Pagination">
 *   <button class="arrow" type="button" aria-label="First page" disabled><span class="pfx-icon -icon-chevrons-left"></span></button>
 *   <button class="arrow" type="button" aria-label="Previous page" disabled><span class="pfx-icon -icon-chevron-left"></span></button>
 *   <a class="page" href="#" aria-current="page">1</a>
 *   <a class="page" href="#">2</a>
 *   <a class="page" href="#">3</a>
 *   <span class="ellipsis">…</span>
 *   <a class="page" href="#">12</a>
 *   <a class="arrow" href="#" aria-label="Next page"><span class="pfx-icon -icon-chevron-right"></span></a>
 *   <a class="arrow" href="#" aria-label="Last page"><span class="pfx-icon -icon-chevrons-right"></span></a>
 * </nav>
 * ```
 * @structure
 * .pfx-pagination {
 *   .arrow {
 *     [class*="-icon-"]:optional {}
 *   }
 *   .page:many {}
 *   .ellipsis:optional {}
 * }
 * @example -automatica11y
 * ```html
 * <nav class="pfx-pagination" aria-label="Pagination">
 *   <button class="arrow" type="button" aria-label="First page" disabled><span class="pfx-icon -icon-chevrons-left"></span></button>
 *   <button class="arrow" type="button" aria-label="Previous page" disabled><span class="pfx-icon -icon-chevron-left"></span></button>
 *   <a class="page" href="#" aria-current="page">1</a>
 *   <a class="page" href="#">2</a>
 *   <a class="page" href="#">3</a>
 *   <span class="ellipsis">…</span>
 *   <a class="page" href="#">12</a>
 *   <a class="arrow" href="#" aria-label="Next page"><span class="pfx-icon -icon-chevron-right"></span></a>
 *   <a class="arrow" href="#" aria-label="Last page"><span class="pfx-icon -icon-chevrons-right"></span></a>
 * </nav>
 * ```
 */
.pfx-pagination {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--instui-component-pagination-page-indicator-gap);
  font-family: var(--instui-font-family-base);
}

@scope (.pfx-pagination) {
  :scope {
    /* A nav arrow — an <a> or <button>. Text-style primary button: brand text, no fill. */
    > .arrow {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-inline-size: 2rem;
      min-block-size: 2rem;
      padding: var(--instui-spacing-space2xs) var(--instui-spacing-space-xs);
      color: var(--instui-color-text-interactive-navigation-primary-base);
      background: transparent;
      border: var(--instui-border-width-md) solid transparent;
      border-radius: var(--instui-component-base-button-border-radius);
      font: inherit;
      font-weight: var(--instui-font-weight-interactive);
      text-decoration: none;
      cursor: pointer;
    }

    > .arrow :is([class^="-icon-"], [class*=" -icon-"]) {
      line-height: 1;
    }

    > .arrow:hover {
      background: var(--instui-color-background-muted);
      color: var(--instui-color-text-interactive-navigation-primary-hover);
    }

    /* Disabled nav arrows (first/prev at page 1, etc.) — shown muted (InstUI showDisabledButtons). */
    > .arrow:disabled,
    > .arrow[aria-disabled="true"] {
      color: var(--instui-color-text-muted);
      background: transparent;
      opacity: var(--instui-opacity-disabled);
      cursor: not-allowed;

      @media (prefers-reduced-transparency: reduce) {
        opacity: 1;
      }
    }

    /* The truncation ellipsis — inert text. */
    > .ellipsis {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-inline-size: 2rem;
      color: var(--instui-color-text-muted);
    }

    /* variant="input" label ("Page … of N"). */
    > .page-input-label {
      color: var(--instui-component-pagination-page-input-label-color);
    }
  }
}

/* variant="input": a "Page [n] of N" jumper (the input width + spacing come from the page-input tokens). */
.pfx-pagination.-variant-input {
  gap: var(--instui-component-pagination-page-input-input-spacing);
}

.pfx-pagination.-variant-input .pfx-text-input,
.pfx-pagination.-variant-input .pfx-number-input {
  inline-size: var(--instui-component-pagination-page-input-input-width);
}

