  expect(coverage.notices).toEqual(results.outcome.coverage);
  expect(coverage.configurations).toHaveLength(12);
  expect(coverage.configurations[1]).toEqual({
    target: "dialog-0",
    archetype: "dialog",
    index: 1,
    state: "open",
    tiers: {
      rules: "ran",
      interactions: "missing",
      computed: "missing",
      conditions: "missing",
      vsr: "ran",
    },
  });
