test("reports missing configurations and rejects malformed coverage data", () => {
  expect(
    collectCoverage({ targets: [{ id: "empty", archetypes: {} }] }, requestedTiers).notices,
  ).toEqual(["empty: no executable configurations"]);
  for (const value of [
    null,
