    { targets: [{ id: "x", archetypes: { dialog: { status: "gap", reason: {} } } }] },
    { targets: [{ id: "x", archetypes: { dialog: { configs: [null] } } }] },
    { targets: [{ id: "x", archetypes: { dialog: { configs: [{}] } } }] },
