    background: transparent;
    border-color: var(--instui-component-base-button-primary-inverse-ghost-border-color);
    color: var(--instui-component-base-button-primary-inverse-ghost-color);
  }

  &.-color-secondary.-on-color:hover {
    background: var(--instui-component-base-button-primary-inverse-ghost-hover-background);
    border-color: var(--instui-component-base-button-primary-on-color-hover-border-color);
    color: var(--instui-component-base-button-secondary-on-color-hover-text-color);
  }

  &.-color-secondary.-on-color:active {
    background: var(--instui-component-base-button-primary-inverse-ghost-active-background);
    border-color: var(--instui-component-base-button-secondary-on-color-active-border-color);
    color: var(--instui-component-base-button-secondary-on-color-active-text-color);
  }

  &.-color-secondary.-on-color:disabled,
  &.-color-secondary.-on-color[aria-disabled="true"] {
    background: transparent;
    border-color: var(--instui-component-base-button-secondary-on-color-disabled-border-color);
    color: var(--instui-component-base-button-secondary-on-color-disabled-text-color);
  }

  /*
   * AI buttons carry two gradients: the fill (padding-box) and a distinct stroke gradient (border-box)
   * that shows through the transparent border — InstUI's ai-primary technique. The ai glyph is added
   * automatically via ::before (appended in index.ts, which needs the shared AI_ICON_MASK constant).
   */
  &.-color-ai {
    color: var(--instui-color-text-interactive-action-ai-base);
    border-color: transparent;
    background:
      linear-gradient(
          to bottom,
          var(--instui-color-background-interactive-action-ai-top-gradient-base) 0%,
          var(--instui-color-background-interactive-action-ai-bottom-gradient-base) 100%
        )
        padding-box,
      linear-gradient(
          to bottom,
          var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
          var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
        )
        border-box;
  }

  &.-color-ai:hover {
    color: var(--instui-color-text-interactive-action-ai-hover);
    background:
      linear-gradient(
          to bottom,
          var(--instui-color-background-interactive-action-ai-top-gradient-hover) 0%,
          var(--instui-color-background-interactive-action-ai-bottom-gradient-hover) 100%
        )
        padding-box,
      linear-gradient(
          to bottom,
          var(--instui-color-stroke-interactive-action-ai-top-gradient-hover) 0%,
          var(--instui-color-stroke-interactive-action-ai-bottom-gradient-hover) 100%
        )
        border-box;
  }

  &.-color-ai:active {
    color: var(--instui-color-text-interactive-action-ai-active);
    background:
      linear-gradient(
          to bottom,
          var(--instui-color-background-interactive-action-ai-top-gradient-active) 0%,
          var(--instui-color-background-interactive-action-ai-bottom-gradient-active) 100%
        )
        padding-box,
      linear-gradient(
          to bottom,
          var(--instui-color-stroke-interactive-action-ai-top-gradient-active) 0%,
          var(--instui-color-stroke-interactive-action-ai-bottom-gradient-active) 100%
        )
        border-box;
  }

  &.-color-ai:disabled,
  &.-color-ai[aria-disabled="true"] {
    color: var(--instui-component-base-button-ai-disabled-text-color);
    border-color: var(--instui-component-base-button-ai-disabled-border-color);
    background: var(--instui-component-base-button-ai-disabled-background-color);
  }

  /*
   * ai-secondary matches InstUI: a transparent rest fill, a violet→sea gradient border ring (::after,
   * masked to just the frame), and violet→sea gradient text (background-clip: text). The ai glyph
   * (::before) picks up the same gradient. A single element can't paint gradient text and a fill at
   * once, so — like InstUI's rest state — the centre stays transparent.
   */
  &.-color-ai-secondary {
    position: relative;
    border-color: transparent;
    background: linear-gradient(
      to bottom,
      var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base) 0%,
      var(--instui-color-text-interactive-action-ai-secondary-bottom-gradient-base) 100%
    );
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }

  /*
   * The ring spans the border-box (outermost) edge, so it isn't inset past the base button's
   * transparent border. The negative inset reaches out over that border; the radius is inherited, so
   * it stays concentric with the button's outer corners.
   */
  &.-color-ai-secondary::after {
    content: "";
    position: absolute;
    inset: calc(-1 * var(--instui-border-width-md));
    border-radius: inherit;
    padding: var(--instui-border-width-sm);
    background: linear-gradient(
      to bottom,
      var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
      var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
    );
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask-composite: exclude;
    pointer-events: none;
  }

  /*
   * Hover/active trade the clipped gradient text for InstUI's subtle gradient fill plus solid text —
   * one element can't paint clipped gradient text and a fill at once, so the interactive states fill.
   */
  &.-color-ai-secondary:hover,
  &.-color-ai-secondary:active {
    -webkit-background-clip: border-box;
    background-clip: border-box;
    color: var(--instui-color-text-interactive-action-ai-secondary-top-gradient-base);
    -webkit-text-fill-color: currentColor;
  }

  &.-color-ai-secondary:hover {
    background: linear-gradient(
      to bottom,
      var(--instui-color-background-interactive-action-ai-secondary-hover-top-gradient) 0%,
      var(--instui-color-background-interactive-action-ai-secondary-hover-bottom-gradient) 100%
    );
  }

  &.-color-ai-secondary:active {
    background: linear-gradient(
      to bottom,
      var(--instui-color-background-interactive-action-ai-secondary-active-top-gradient) 0%,
      var(--instui-color-background-interactive-action-ai-secondary-active-bottom-gradient) 100%
    );
  }

  &.-color-ai-secondary:disabled,
  &.-color-ai-secondary[aria-disabled="true"] {
    background: transparent;
    border-color: var(--instui-component-base-button-ai-disabled-border-color);
    color: var(--instui-component-base-button-ai-disabled-text-color);
    -webkit-text-fill-color: currentColor;
  }

  /* The ai glyph's background; the mask itself is appended in index.ts (needs the shared AI_ICON_MASK). */
  &.-color-ai::before {
    background: var(--instui-color-text-interactive-action-ai-base);
  }

  &.-color-ai-secondary::before {
    background: linear-gradient(
      to bottom,
      var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
      var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
    );
  }

  &.-color-ai:is([class^="-icon-"], [class*=" -icon-"])::before {
    background: currentColor;
  }

  &.-color-ai-secondary:is([class^="-icon-"], [class*=" -icon-"])::before {
    background: linear-gradient(
      to bottom,
      var(--instui-color-stroke-interactive-action-ai-top-gradient-base) 0%,
      var(--instui-color-stroke-interactive-action-ai-bottom-gradient-base) 100%
    );
  }

  &.-color-ai:disabled::before,
  &.-color-ai[aria-disabled="true"]::before,
  &.-color-ai-secondary:disabled::before,
  &.-color-ai-secondary[aria-disabled="true"]::before {
    background: var(--instui-component-icon-action-ai-disabled-color);
  }

  /*
   * --without-background is InstUI's withBackground={false}: a transparent button in the
   * primary ghost tokens. `-ghost` is a deprecated alias of `-color-tertiary` above.
   */
  &.-without-background {
    background: var(--instui-component-base-button-primary-ghost-background);
    color: var(--instui-component-base-button-primary-ghost-color);
    border-color: var(--instui-component-base-button-primary-ghost-border-color);
  }

  /* --block is InstUI's display="block": a full-width button. */
  &.-display-block {
    display: flex;
    width: 100%;
  }

  &.-size-sm {
    font-size: var(--instui-component-base-button-small-font-size);
    min-height: var(--instui-component-base-button-small-height);
    padding-inline: var(--instui-component-base-button-small-padding-horizontal);
  }

  &.-size-sm:is(
      .-shape-square,
      :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
          :has(> :not(.pfx-screen-reader-content):not(.tip))
        )
    ) {
    inline-size: var(--instui-component-base-button-small-height);
  }

  &.-size-md {
    font-size: var(--instui-component-base-button-medium-font-size);
    min-height: var(--instui-component-base-button-medium-height);
    padding-inline: var(--instui-component-base-button-medium-padding-horizontal);
  }

  &.-size-md:is(
      .-shape-square,
      :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
          :has(> :not(.pfx-screen-reader-content):not(.tip))
        )
    ) {
    inline-size: var(--instui-component-base-button-medium-height);
  }

  &.-size-lg {
    font-size: var(--instui-component-base-button-large-font-size);
    min-height: var(--instui-component-base-button-large-height);
    padding-inline: var(--instui-component-base-button-large-padding-horizontal);
  }

  &.-size-lg:is(
      .-shape-square,
      :is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child),
      :is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
          :has(> :not(.pfx-screen-reader-content):not(.tip))
        )
    ) {
    inline-size: var(--instui-component-base-button-large-height);
  }

  &.-shape-square,
  &:is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *)),
  &:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child),
  &:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
      :has(> :not(.pfx-screen-reader-content):not(.tip))
    ) {
    padding: var(--instui-spacing-space-xs);
    aspect-ratio: 1;
  }

  &.-shape-circle {
    padding: var(--instui-spacing-space-xs);
    aspect-ratio: 1;
    border-radius: 50%;
  }

  /*
   * A composed `-icon-<name>` rides the shared icon painter (utilities/icon), so a text button needs no
   * button-specific glyph CSS — the ::before already inherits the label's colour and 1em size. Icon-only
   * shape buttons carry no label, so grow the glyph to fill the square control rather than tracking a
   * (missing) label's cap height.
   */
  &:is([class^="-icon-"], [class*=" -icon-"])::before {
    display: inline-block;
    inline-size: 1em;
    block-size: 1em;
    flex: none;
    margin-inline-end: var(--instui-spacing-space-xs);
    vertical-align: -0.125em;
    background: currentColor;
    -webkit-mask: var(--pantoken-glyph) center / contain no-repeat;
    mask: var(--pantoken-glyph) center / contain no-repeat;
  }

  &.-shape-square:is([class^="-icon-"], [class*=" -icon-"])::before,
  &.-shape-circle:is([class^="-icon-"], [class*=" -icon-"])::before,
  &:is([class^="-icon-"], [class*=" -icon-"]):not(:has(> *))::before,
  &:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content:only-child)::before,
  &:is([class^="-icon-"], [class*=" -icon-"]):has(> .pfx-screen-reader-content):has(> .tip):not(
      :has(> :not(.pfx-screen-reader-content):not(.tip))
    )::before {
    inline-size: 1.25em;
    block-size: 1.25em;
    margin-inline-end: 0;
  }

  &.-condensed {
    background: transparent;
    border-color: transparent;
    min-height: 0;
    color: var(--instui-color-text-interactive-action-secondary-base);
    padding-inline: var(--instui-spacing-space-xs);
  }

  &.-condensed:hover {
    background: var(--instui-color-background-muted);
  }

  &.-toggle[aria-pressed="true"] {
    background: var(--instui-color-background-interactive-action-secondary-active);
    border-color: var(--instui-color-stroke-interactive-action-secondary-active);
    color: var(--instui-color-text-interactive-action-secondary-base);
  }

  /* InstUI's withBorder={false}: drop the border but keep the button's box (border-box sizing). */
  &.-without-border {
    border-style: none;
  }

  &.-color-ai-secondary.-without-border::after {
    display: none;
  }

  @media (forced-colors: active) {
    &.-color-ai-secondary {
      &,
      &:is(:hover, :active, :disabled, [aria-disabled="true"]) {
        background: none;
        color: ButtonText;
        -webkit-text-fill-color: currentColor;
      }

      &:is(:disabled, [aria-disabled="true"]) {
        color: GrayText;
      }
    }

    &:is(.-color-ai, .-color-ai-secondary) {
      &::before,
      &:is(:disabled, [aria-disabled="true"])::before,
      &:is([class^="-icon-"], [class*=" -icon-"])::before {
        forced-color-adjust: preserve-parent-color;
        background: currentColor;
      }
    }

    &.-color-ai-secondary::after,
    &:is([class^="-icon-"], [class*=" -icon-"])::before {
      forced-color-adjust: preserve-parent-color;
      background: currentColor;
    }
  }
}

.pfx-button-group {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--instui-component-shared-tokens-spacing-gap-buttons);
}

