/**
 * @component alert
 * @summary A status message with floating and inline surface treatments and a masked status glyph from the shared icon set.
 * @remarks Floating is the default, with an elevated coloured surface and on-colour actions. `-inline` uses a pastel surface, no shadow, status-coloured glyph, standard close button, primary action, and tertiary secondary action. A single direct action button forms a row after unwrapped text; wrap two actions in `.button-group`, where they become secondary then primary. Any button modifier opts out of this automatic variant assignment. A direct close button defaults to small; add a size modifier to override it.
 * @selector .pfx-alert
 * @modifier -color-info — Informational (default).
 * @modifier -color-success — A positive/confirmation message.
 * @modifier -color-warning — A cautionary message.
 * @modifier -color-danger — An error message.
 * @modifier -color-error — @alias {@link -color-danger}
 * @modifier -inline — A non-elevated pastel surface for placement in document flow.
 * @modifier -without-shadow — @deprecated {@link -inline}
 * @modifier -has-shadow-false — @alias {@link -without-shadow}
 * @modifier -screen-reader-only — Visually hidden but announced.
 * @modifier -variant-info — @deprecated {@link -color-info}
 * @modifier -variant-success — @deprecated {@link -color-success}
 * @modifier -variant-warning — @deprecated {@link -color-warning}
 * @modifier -variant-error — @deprecated {@link -color-danger}
 * @modifier -timeout — @interaction The alert will automatically dismiss after a default of 5 seconds.
 * @modifier -timeout-1 — One second before automatic dismissal.
 * @modifier -timeout-2 — Two seconds before automatic dismissal.
 * @modifier -timeout-3 — Three seconds before automatic dismissal.
 * @modifier -timeout-4 — Four seconds before automatic dismissal.
 * @modifier -timeout-5 — Five seconds before automatic dismissal.
 * @part button-group — The row container for two action buttons.
 * @slot content — The alert's message content; may include a dismiss button.
 * @modifier -icon-* — Swap the status glyph for a custom icon (e.g. `-icon-megaphone`).
 * @pseudo ::after — The status glyph, masked and padded independently from the content.
 * @cssproperty --pantoken-alert-glyph <url> — The low-level status-glyph source; `-icon-<name>` sets it for you. Override for a custom icon (a url-encoded SVG).
 * @cssproperty --pantoken-alert-icon-bg <color> — The coloured status-bar fill behind the glyph; each `-color-*` variant sets its own.
 * @cssproperty --timeout <integer> — Milliseconds before automatic dismissal; `0` disables it. Requires the alert interaction bundle.
 * @accessibility For an important message, add `role="alert"` or an `aria-live` region so assistive tech announces it; the dismiss control is a labelled close button (the `.pfx-close-button` in the example carries `aria-label="Close"`).
 * @example -canvas-rce-no-interactions -nocard
 * ```html
 * <div class="pfx-alert" role="status">Settings saved.</div>
 * ```
 * @example -canvas-rce -nocard
 * ```html
 * <div class="pfx-alert" role="status">
 *   Settings saved.
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 *
 * ```
 * @example -docs -nocard
 * ```html
 * <div class="pfx-alert -icon-megaphone --mb-md">
 *   An alert with the default info color, and a custom icon.
 * </div>
 * <div class="pfx-alert -icon-megaphone -inline --mb-md">
 *   An alert with the default info color, and a custom icon.
 * </div>
 * <div class="pfx-alert -color-success --mb-md">
 *   Congratulations! You're using the "success" color.
 *     <button class="pfx-button">Ok</button>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * <div class="pfx-alert -color-success -inline --mb-md">
 *   Congratulations! You're using the "success" color.
 *     <button class="pfx-button">Ok</button>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * <div class="pfx-alert -color-error --mb-md">
 *   Oops! You're using the "error" color.
 *   <div class="button-group">
 *     <button class="pfx-button">Cancel</button>
 *     <button class="pfx-button">Ok</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * <div class="pfx-alert -color-error -inline --mb-md">
 *   Oops! You're using the "error" color.
 *   <div class="button-group">
 *     <button class="pfx-button">Cancel</button>
 *     <button class="pfx-button">Ok</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * <div class="pfx-alert -color-warning --mb-md">
 *   Watch out! You're using the "warning" color.
 *   <div class="button-group">
 *     <button class="pfx-button">Cancel</button>
 *     <button class="pfx-button">Ok</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * <div class="pfx-alert -color-warning -inline --mb-md">
 *   Watch out! You're using the "warning" color.
 *   <div class="button-group">
 *     <button class="pfx-button">Cancel</button>
 *     <button class="pfx-button">Ok</button>
 *   </div>
 *   <button class="pfx-close-button" aria-label="Close"></button>
 * </div>
 * ```
 * @example -automatica11y -nocard
 * ```html
 * <div data-a11y-root>
 *   <div class="pfx-alert -color-info --mb-md" role="status">Your export is ready.</div>
 *   <div class="pfx-alert -color-success --mb-md" role="status">Settings saved.</div>
 *   <div class="pfx-alert -color-warning --mb-md" role="alert">Your session expires soon.</div>
 *   <div class="pfx-alert -color-danger --mb-md" role="alert">The upload failed.</div>
 *   <div class="pfx-alert -color-info -inline --mb-md" role="status">An update is available.</div>
 *   <div class="pfx-alert -color-success -inline --mb-md" role="status">Your changes are published.</div>
 *   <div class="pfx-alert -color-warning -inline --mb-md" role="alert">Save your work before leaving.</div>
 *   <div class="pfx-alert -color-danger -inline --mb-md" role="alert">Check the file and try again.</div>
 *   <div class="pfx-alert -icon-megaphone --mb-md" role="status">Registration opens tomorrow.</div>
 *   <div class="pfx-alert -icon-megaphone -inline --mb-md" role="status">Registration is now open.</div>
 *   <div class="pfx-alert -screen-reader-only" role="status">All changes saved.</div>
 *   <div class="pfx-alert -timeout-5" role="status">A copy was saved automatically.</div>
 * </div>
 * ```
 * @structure
 * .pfx-alert {
 *   slot {}
 *   @variant bare-button {
 *     @component button:max-1 {}
 *   }
 *   @variant button-group {
 *     .button-group {
 *       @component button:one-or-more:max-2 {}
 *     }
 *   }
 *   @component close-button:optional {}
 * }
 * @related close-button — The dismiss control an alert may include.
 * @sealed
 * @stable
 */
@property --timeout {
  syntax: "<integer>";
  inherits: false;
  initial-value: 5;
}

@scope (.pfx-alert) {
  & {
    --timeout: 0;
    position: relative;
    min-inline-size: 12rem;
    padding: var(--instui-component-alert-content-padding-vertical)
      var(--instui-component-alert-content-padding-horizontal);
    padding-inline-start: calc(
      0.833rem + var(--instui-component-alert-icon-padding-left) + 0.75rem
    );
    background: var(--instui-component-alert-info-background);
    color: var(--instui-component-text-base-on-color);
    border: var(--instui-component-alert-border-width) var(--instui-component-alert-border-style)
      var(--instui-component-alert-info-border-color);
    border-radius: var(--instui-component-alert-border-radius);
    box-shadow:
      0 4px 4px 0 var(--instui-color-drop-shadow-shadow-color1),
      0 var(--instui-drop-shadow-y-elevation4-dropshadow1)
        var(--instui-drop-shadow-blur-elevation4-dropshadow1)
        var(--instui-drop-shadow-spread-elevation4-dropshadow1)
        var(--instui-color-drop-shadow-shadow-color1);
    font-family: var(--instui-component-alert-content-font-family);
    font-size: var(--instui-component-alert-content-font-size);
    font-weight: var(--instui-component-alert-content-font-weight);
    line-height: var(--instui-component-alert-content-line-height);
    --pantoken-alert-icon-color: var(--instui-color-icon-on-color);
    --pantoken-alert-glyph: var(--instui-icon-info);

    /* Close/dismiss is optional: pin it in the top-end corner (the button's own box centres the ×, so it
     takes a small symmetric inset, not the content padding), and reserve room only when it's present. */
    > .pfx-close-button:not([class*="-size-"]) {
      min-height: var(--instui-component-base-button-small-height);
    }

    > .pfx-close-button {
      position: absolute;
      inset-block-start: var(--instui-spacing-space-xs);
      inset-inline-end: var(--instui-spacing-space-xs);
      color: var(--instui-color-icon-on-color);
    }
  }

  /* The glyph carries its own token-defined padding rather than sitting on a coloured bar. */
  &::after {
    content: "";
    position: absolute;
    inset-block-start: var(--instui-component-alert-icon-padding-vertical);
