/**
 * @component checkbox
 * @summary A native checkbox and its label, or a switch via `-variant-toggle`.
 * @remarks Set `el.indeterminate = true` in JavaScript to show the mixed-state dash; the checked tick auto-contrasts against the fill — white on a dark fill, near-black on a light one. Also sets its own `gap` between the control and its label; chaining a `-gap-*` spacing utility modifier overrides that built-in value.
 * @modifier -invalid — Invalid (error) state.
 * @modifier -label-placement-end — Place the label after the control.
 * @modifier -label-placement-start — Place the label before the control.
 * @modifier -label-placement-top — Place the label above the control.
 * @modifier -readonly — Read-only state.
 * @modifier -required — Show the required-field asterisk next to the label.
 * @modifier -variant-toggle — Render as a switch instead of a box.
 * @modifier -size-sm — Small.
 * @modifier -size-lg — Large.
 * @part .asterisk — The required-field asterisk.
 * @pseudo ::before — The masked tick or dash glyph centered in the box; on `-variant-toggle` it becomes the sliding handle instead.
 * @pseudo ::after — On `-variant-toggle`, the state glyph riding the handle: an X when off, a check when on.
 * @cssproperty --pantoken-cb-glyph <url> — The box's mask glyph: a tick when checked, a dash when indeterminate.
 * @cssproperty --pantoken-toggle-h <length> — The toggle switch height.
 * @cssproperty --pantoken-toggle-w <length> — The toggle track width.
 * @cssproperty --pantoken-toggle-bw <length> — The toggle border width.
 * @cssproperty --pantoken-toggle-inset <length> — The handle inset from each track edge.
 * @cssproperty --pantoken-toggle-handle <length> — The computed handle diameter.
 * @cssstate checked
 * @cssstate indeterminate
 * @cssstate disabled
 * @accessibility Wrap the native `<input type="checkbox">` and its visible text in a `<label>` to supply its accessible name. The input drives `:checked`, `:indeterminate`, and `:disabled`; set `el.indeterminate = true` in JavaScript for the mixed state. `-readonly` is styling only since checkboxes have no native readonly attribute.
 * @example -canvas-rce -docs
 * ```html
 * <label class="pfx-checkbox --display-block --mb-sm">
 *   <input type="checkbox" checked>Checkbox
 * </label>
 * <label class="pfx-checkbox -variant-toggle">
 *   <input type="checkbox">Toggle
 * </label>
 * ```
 * @related radio — The single-select counterpart.
 * @example -automatica11y
 * ```html
 * <p><label class="pfx-checkbox"><input type="checkbox">Unchecked checkbox</label></p>
 * <p><label class="pfx-checkbox -label-placement-end"><input type="checkbox" checked>Checked checkbox, label after</label></p>
 * <p><label class="pfx-checkbox -size-sm -label-placement-start"><input type="checkbox" checked>Small checkbox, label before</label></p>
 * <p><label class="pfx-checkbox -size-lg -label-placement-top"><input type="checkbox">Large checkbox, label above</label></p>
 * <p><label class="pfx-checkbox"><input id="audit-checkbox-mixed" type="checkbox">Partially selected checkbox</label></p>
 * <p><label class="pfx-checkbox"><input type="checkbox" disabled>Disabled unchecked checkbox</label></p>
 * <p><label class="pfx-checkbox"><input type="checkbox" checked disabled>Disabled checked checkbox</label></p>
 * <p><label class="pfx-checkbox -readonly"><input type="checkbox" checked disabled>Locked checkbox (disabled because native checkboxes have no readonly state)</label></p>
 * <p><label class="pfx-checkbox -invalid -required"><input type="checkbox" required aria-invalid="true" aria-describedby="audit-checkbox-error">Accept the terms (required)<span class="asterisk" aria-hidden="true">*</span></label></p>
 * <p id="audit-checkbox-error">Accept the terms before continuing.</p>
 * <p><label class="pfx-checkbox -variant-toggle"><input type="checkbox">Toggle off</label></p>
 * <p><label class="pfx-checkbox -variant-toggle"><input type="checkbox" checked>Toggle on</label></p>
 * <p><label class="pfx-checkbox -variant-toggle -size-sm"><input type="checkbox" checked>Small toggle on</label></p>
 * <p><label class="pfx-checkbox -variant-toggle -size-lg"><input type="checkbox">Large toggle off</label></p>
 * <p><label class="pfx-checkbox -variant-toggle"><input type="checkbox" disabled>Disabled toggle off</label></p>
 * <p><label class="pfx-checkbox -variant-toggle"><input type="checkbox" checked disabled>Disabled toggle on</label></p>
 * <script>document.getElementById("audit-checkbox-mixed").indeterminate = true;</script>
 * ```
 */
.pfx-checkbox {
  display: inline-flex;
  align-items: center;
  gap: var(--instui-component-checkbox-gap);
  color: var(--instui-component-checkbox-label-base-color);
  font-family: var(--instui-component-checkbox-font-family);
  font-size: var(--instui-component-checkbox-font-size-md);
  font-weight: var(--instui-component-checkbox-font-weight);
  line-height: var(--instui-component-checkbox-line-height);
}

/* labelPlacement: the control comes first in the markup, so reorder with flex. Default is "end"
   (label after the control); "start" puts it before, "top" stacks it above. */
.pfx-checkbox.-label-placement-end {
  flex-direction: row;
}

.pfx-checkbox.-label-placement-start {
  flex-direction: row-reverse;
}

.pfx-checkbox.-label-placement-top {
  flex-direction: column-reverse;
  align-items: flex-start;
}

/* Base control: a native checkbox restyled via appearance:none so the InstUI border/background/checked
   tokens all apply, with the tick masked into a ::before. Scoped away from the --toggle switch. */
.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"] {
  --pantoken-cb-glyph: var(--instui-icon-check) center / contain no-repeat;
  appearance: none;
  -webkit-appearance: none;
  display: inline-grid;
  place-content: center;
  flex: none;
  width: var(--instui-component-checkbox-control-size-md);
  height: var(--instui-component-checkbox-control-size-md);
  margin-block: var(--instui-component-checkbox-control-vertical-margin);
  border: var(--instui-component-checkbox-border-width) solid
    var(--instui-component-checkbox-border-color);
  border-radius: var(--instui-component-checkbox-border-radius);
  background: var(--instui-component-checkbox-background-color);
  cursor: pointer;

  @media (prefers-reduced-motion: no-preference) {
    transition:
      background-color 0.15s ease,
      border-color 0.15s ease;
  }
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]::before {
  content: "";
  width: 0.75em;
  height: 0.75em;
  /* Auto-contrast the tick against the checked fill: white on a dark fill, near-black on a light one.
     The fill token is light-dark(), so a fixed on-color would vanish in one scheme. */
  background: oklch(
    from var(--instui-component-checkbox-background-checked-color)
      clamp(0, (0.62 - l) * infinity, 1) 0 0
  );
  -webkit-mask: var(--pantoken-cb-glyph);
  mask: var(--pantoken-cb-glyph);
  @media (forced-colors: active) {
    forced-color-adjust: preserve-parent-color;
    background: currentColor;
  }
  transform: scale(0);
  @media (prefers-reduced-motion: no-preference) {
    transition: transform 0.1s ease;
  }
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:hover {
  border-color: var(--instui-component-checkbox-border-hover-color);
  background: var(--instui-component-checkbox-background-hover-color);
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:checked,
.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:indeterminate {
  border-color: var(--instui-component-checkbox-border-checked-color);
  background: var(--instui-component-checkbox-background-checked-color);
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:checked::before,
.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:indeterminate::before {
  transform: scale(1);
}

/* Indeterminate (mixed) state: a dash in place of the tick. Set el.indeterminate = true in JS. */
.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:indeterminate {
  --pantoken-cb-glyph: var(--instui-icon-minus) center / contain no-repeat;
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle) input[type="checkbox"]:disabled {
  border-color: var(--instui-component-checkbox-border-disabled-color);
  background: var(--instui-component-checkbox-background-disabled-color);
  cursor: not-allowed;
}

.pfx-checkbox:has(input:disabled) {
  color: var(--instui-component-checkbox-label-disabled-color);
}

.pfx-checkbox:hover {
  color: var(--instui-component-checkbox-label-hover-color);
}

.pfx-checkbox.-size-sm {
  font-size: var(--instui-component-checkbox-font-size-sm);
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle).pfx-checkbox.-size-sm input[type="checkbox"] {
  width: var(--instui-component-checkbox-control-size-sm);
  height: var(--instui-component-checkbox-control-size-sm);
}

.pfx-checkbox.-size-lg {
  font-size: var(--instui-component-checkbox-font-size-lg);
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle).pfx-checkbox.-size-lg input[type="checkbox"] {
  width: var(--instui-component-checkbox-control-size-lg);
  height: var(--instui-component-checkbox-control-size-lg);
}

.pfx-checkbox:not(.pfx-checkbox.-variant-toggle).pfx-checkbox.-invalid input[type="checkbox"] {
