/**
 * @component badge
 * @selector .pfx-badge
 * @a11y The count or dot is visual only, so don't rely on color to carry its meaning; put the status in text, such as visually hidden text or an `aria-label` on the target it decorates.
 * @summary A small count or status dot placed over a target's corner.
 * @modifier -color-success — A positive/complete count.
 * @modifier -color-danger — An attention/error count.
 * @modifier -color-inverse — On-dark: a light chip with dark text.
 * @modifier -type-notification — A dot only, no count.
 * @modifier -pulse — A pulsing attention ring.
 * @modifier -standalone — Render inline, not positioned over a target's corner.
 * @modifier -placement-top-start — Position at the top-start corner.
 * @modifier -placement-top-end — Position at the top-end corner.
 * @modifier -placement-bottom-start — Position at the bottom-start corner.
 * @modifier -placement-bottom-end — Position at the bottom-end corner.
 * @modifier -placement-start-center — Position centred on the start edge.
 * @modifier -placement-end-center — Position centred on the end edge.
 * @pseudo ::before — The pulsing attention ring drawn in the badge's accent colour (the `-pulse` variant).
 * @cssproperty --pantoken-badge-accent <color> — The chip fill; each `-color-*` variant and the pulse ring read from it.
 * @cssproperty --pantoken-badge-text <color> — The text colour, paired to the accent so it stays legible.
 * @remarks To place a badge over a target, wrap both in a `.pfx-badge-wrapper` (the position anchor) and pin the badge with a `-placement-*` modifier.
 * @animation pantoken-badge-pulse — The pulse ring animation.
 * @example -canvas-rce -docs
 * ```html
 * <span class="pfx-badge-wrapper">
 *   <button class="pfx-button">Inbox</button>
 *   <span class="pfx-badge -placement-top-end">4</span>
 * </span>
 * ```
 * @wrapper pfx-badge-wrapper
 * @structure
 * The badge renders inline on its own, or inside an optional `pfx-badge-wrapper` that anchors it over a target.
 * .pfx-badge-wrapper:opt {
 *   slot {}
 *   .pfx-badge {}
 * }
 * @related pill — The inline label-chip counterpart.
 * @demo self:badge
 * @example -automatica11y
 * ```html
 * <div><span class="pfx-badge -standalone" aria-label="4 unread messages">4</span></div>
 * <div><span class="pfx-badge -standalone -color-success" aria-label="2 completed reviews">2</span></div>
 * <div><span class="pfx-badge -standalone -color-danger" aria-label="3 failed uploads">3</span></div>
 * <div class="--bg-inverse --p-md"><span class="pfx-badge -standalone -color-inverse" aria-label="5 new notices">5</span></div>
 * <div><span class="pfx-badge -standalone -type-notification" role="img" aria-label="New message"></span></div>
 * <div><span class="pfx-badge -standalone -pulse" aria-label="1 pending invitation">1</span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-top-start" aria-label="4 unread">4</span></span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-top-end" aria-label="4 unread">4</span></span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-bottom-start" aria-label="4 unread">4</span></span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-bottom-end" aria-label="4 unread">4</span></span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-start-center" aria-label="4 unread">4</span></span></div>
 * <div class="--p-md"><span class="pfx-badge-wrapper">Unread messages<span class="pfx-badge -placement-end-center" aria-label="4 unread">4</span></span></div>
 * ```
 */
@keyframes pantoken-badge-pulse {
  from {
    transform: scale(1);
    opacity: 0.7;
  }

  to {
    transform: scale(1.8);
    opacity: 0;
  }
}

/* Wrap a target in this so a placed badge can sit over its corner. It contains the badge (rather than
   being contained by it), so it's a flat prefixed class, not a scoped element. */
.pfx-badge-wrapper {
  position: relative;
  display: inline-flex;
}

@scope (.pfx-badge) {
  :scope {
    --pantoken-badge-accent: var(--instui-component-badge-color-primary);
    /* The primary fill is the brand colour, which flips dark→light between light and dark mode; pair the
       text so it stays legible either way (white on the light-mode navy, dark on the dark-mode light
       fill). The saturated status fills below keep white text in both modes. */
    --pantoken-badge-text: light-dark(
      var(--instui-component-badge-color),
      var(--instui-component-badge-color-inverse)
    );
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--instui-component-badge-size);
    height: var(--instui-component-badge-size);
    padding: 0 var(--instui-component-badge-padding);
    font-family: var(--instui-component-badge-font-family);
    font-size: var(--instui-component-badge-font-size);
    font-weight: var(--instui-component-badge-font-weight);
    line-height: 1;
    border-radius: var(--instui-component-badge-border-radius);
    background: var(--pantoken-badge-accent);
    color: var(--pantoken-badge-text);

    &.-color-success {
      --pantoken-badge-accent: var(--instui-component-badge-color-success);
      --pantoken-badge-text: var(--instui-component-badge-color);
    }

    &.-color-danger {
      --pantoken-badge-accent: var(--instui-component-badge-color-danger);
      --pantoken-badge-text: var(--instui-component-badge-color);
    }

    /* Inverse swaps fill and text (InstUI): a light chip with dark text, for a colour/dark surface. */
    &.-color-inverse {
      --pantoken-badge-accent: var(--instui-component-badge-color);
      --pantoken-badge-text: var(--instui-component-badge-color-inverse);
    }

    /* Notification: a small dot, no count. */
    &.-type-notification {
      min-width: 0;
      width: var(--instui-spacing-space-sm);
      height: var(--instui-spacing-space-sm);
      padding: 0;
      font-size: 0;
    }

    /* Pulse: an expanding ring in the badge's accent colour (InstUI `pulse`). */
    &.-pulse::before {
      content: "";
      position: absolute;
      inset: 0;
      border: var(--instui-border-width-md) solid var(--pantoken-badge-accent);
      border-radius: inherit;
      @media (prefers-reduced-motion: no-preference) {
        animation: pantoken-badge-pulse 1.2s ease-out infinite;
      }
    }

    /* Placement: position the badge over a `.badge-wrapper` target. InstUI's countOffset is 0.5rem. */
    &.-placement-top-end,
    &.-placement-top-start,
    &.-placement-bottom-end,
    &.-placement-bottom-start,
    &.-placement-start-center,
    &.-placement-end-center {
      position: absolute;
    }

    &.-placement-top-end {
      top: -0.5rem;
      inset-inline-end: -0.5rem;
    }

    &.-placement-top-start {
      top: -0.5rem;
      inset-inline-start: -0.5rem;
    }

    &.-placement-bottom-end {
      bottom: -0.5rem;
      inset-inline-end: -0.5rem;
    }

    &.-placement-bottom-start {
      bottom: -0.5rem;
      inset-inline-start: -0.5rem;
    }

    &.-placement-end-center {
      top: 50%;
      inset-inline-end: -0.5rem;
      transform: translateY(-50%);
    }

    &.-placement-start-center {
      top: 50%;
      inset-inline-start: -0.5rem;
      transform: translateY(-50%);
    }

    /* Standalone: the inline chip, in flow — resets any placement. */
    &.-standalone {
      position: relative;
      inset: auto;
      transform: none;
    }
  }
}

